window.__ROI_HTML__ = "<!DOCTYPE html>\r\n<html lang=\"th\" data-theme=\"light\" class=\"embed\">\r\n<head><script>try{window.localStorage.getItem(\"x\");}catch(e){try{Object.defineProperty(window,\"localStorage\",{value:{getItem:function(){return null;},setItem:function(){},removeItem:function(){}}}});}catch(_){}}<\/script>\r\n<meta charset=\"UTF-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n<script>try{if(location.search.indexOf('embed')>-1)document.documentElement.classList.add('embed');}catch(e){}<\/script>\r\n<meta name=\"theme-color\" content=\"#0b1220\">\r\n<title>ROI Studio · วิเคราะห์การลงทุน &amp; ค่างวด</title>\r\n<meta name=\"description\" content=\"เครื่องมือวิเคราะห์การลงทุนตู้หยอดเหรียญ: ROI, Payback, NPV, IRR, จุดคุ้มทุน และคำนวณค่างวด/ดอกเบี้ยทั้งแบบ Flat rate และลดต้นลดดอก\">\r\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\r\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\r\n<link href=\"https://fonts.googleapis.com/css2?family=Prompt:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\r\n<style>\r\n*{box-sizing:border-box}\r\nhtml,body{margin:0;padding:0}\r\n:root{\r\n  --bg:#f2f6fc; --surface:#fff; --surface-2:#f7f9fd; --surface-3:#edf2fb;\r\n  --ink:#0d1526; --ink-2:#4a5768; --ink-3:#8b98ac; --line:#e3e9f3; --line-2:#eff3f9;\r\n  --brand:#3b5bfd; --brand-2:#0fb5a5; --brand-soft:#eef1ff;\r\n  --ok:#0e9f6e; --ok-soft:#e8f8f1; --warn:#b97708; --warn-soft:#fdf4e3; --bad:#d63d3d; --bad-soft:#fdeaea;\r\n  --shadow:0 12px 32px rgba(16,32,64,.07); --shadow-sm:0 2px 8px rgba(16,32,64,.05);\r\n  --r-lg:18px; --r-md:12px; --r-sm:9px;\r\n  --grid:#e7edf7;\r\n  --c-raw:#f59e0b; --c-qr:#38bdf8; --c-elec:#facc15; --c-water:#60a5fa;\r\n  --c-fix:#a78bfa; --c-loan:#fb7185; --c-profit:#10b981;\r\n}\r\n[data-theme=\"dark\"]{\r\n  --bg:#080e1c; --surface:#111a2b; --surface-2:#151f33; --surface-3:#1a2539;\r\n  --ink:#e9eefb; --ink-2:#a9b6cd; --ink-3:#6d7d9a; --line:#22304a; --line-2:#1b2740;\r\n  --brand:#6b83ff; --brand-2:#2ed3c2; --brand-soft:#1a2544;\r\n  --ok:#34d399; --ok-soft:#10291f; --warn:#f0b429; --warn-soft:#2a2110; --bad:#f87171; --bad-soft:#2b1414;\r\n  --shadow:0 16px 38px rgba(0,0,0,.5); --shadow-sm:0 2px 10px rgba(0,0,0,.32);\r\n  --grid:#223049;\r\n}\r\nbody{\r\n  min-height:100vh; color:var(--ink); font-size:13.5px; line-height:1.5;\r\n  font-family:\"Prompt\",\"Noto Sans Thai\",system-ui,-apple-system,\"Segoe UI\",sans-serif;\r\n  -webkit-font-smoothing:antialiased;\r\n  background:\r\n    radial-gradient(1100px 520px at 8% -12%, rgba(59,91,253,.14), transparent 62%),\r\n    radial-gradient(900px 480px at 96% -6%, rgba(15,181,165,.13), transparent 58%),\r\n    var(--bg);\r\n}\r\nh1,h2,h3,h4,p{margin:0}\r\nbutton{font:inherit;color:inherit;cursor:pointer;border:0;background:none}\r\ninput,select{font:inherit;color:inherit}\r\n::selection{background:rgba(59,91,253,.22)}\r\n\r\n/* ---------- top bar ---------- */\r\n.topbar{\r\n  position:sticky; top:0; z-index:40; display:flex; align-items:center; gap:14px;\r\n  padding:10px 22px; background:color-mix(in srgb, var(--surface) 82%, transparent);\r\n  backdrop-filter:blur(14px); border-bottom:1px solid var(--line);\r\n}\r\n.brand{display:flex;align-items:center;gap:11px;min-width:0}\r\n.mark{\r\n  width:38px;height:38px;border-radius:12px;display:grid;place-items:center;flex:0 0 auto;\r\n  background:linear-gradient(140deg,var(--brand),var(--brand-2));color:#fff;\r\n  font-weight:700;font-size:11.5px;letter-spacing:.04em;box-shadow:0 6px 16px rgba(59,91,253,.35);\r\n}\r\n.brand strong{display:block;font-size:14px;font-weight:600;letter-spacing:-.01em}\r\n.brand small{display:block;font-size:10px;color:var(--ink-3);margin-top:1px}\r\n.top-actions{margin-left:auto;display:flex;align-items:center;gap:8px;flex-wrap:wrap}\r\n.pill{\r\n  display:inline-flex;align-items:center;gap:6px;padding:6px 12px;border-radius:999px;\r\n  border:1px solid var(--line);background:var(--surface);font-size:11.5px;color:var(--ink-2);white-space:nowrap;\r\n}\r\n.pill b{color:var(--ink);font-weight:600}\r\n.btn{\r\n  display:inline-flex;align-items:center;justify-content:center;gap:6px;padding:8px 13px;border-radius:10px;\r\n  border:1px solid var(--line);background:var(--surface);font-size:12px;font-weight:500;color:var(--ink-2);\r\n  transition:.16s ease; white-space:nowrap;\r\n}\r\n.btn:hover{border-color:var(--brand);color:var(--brand);box-shadow:var(--shadow-sm)}\r\n.btn.solid{background:linear-gradient(135deg,var(--brand),#5b7bff);color:#fff;border-color:transparent;box-shadow:0 8px 20px rgba(59,91,253,.3)}\r\n.btn.solid:hover{color:#fff;filter:brightness(1.05)}\r\n.btn.icon{width:36px;padding:0;height:36px;font-size:15px}\r\n\r\n/* ---------- layout ---------- */\r\n.app{\r\n  display:grid; grid-template-columns:minmax(340px,398px) minmax(0,1fr); gap:18px;\r\n  max-width:1500px; margin:0 auto; padding:18px 22px 56px; align-items:start;\r\n}\r\n.stack{display:grid;gap:14px}\r\n.card{\r\n  background:var(--surface); border:1px solid var(--line); border-radius:var(--r-lg); box-shadow:var(--shadow-sm);\r\n}\r\n.card-head{display:flex;align-items:center;gap:8px;padding:14px 16px;border-bottom:1px solid var(--line-2)}\r\n.card-head h2{font-size:12.5px;font-weight:600;letter-spacing:.01em;display:flex;align-items:center;gap:8px}\r\n.card-head .hint{margin-left:auto;font-size:10.5px;color:var(--ink-3);font-weight:300}\r\n.card-body{padding:16px}\r\n.eyebrow{font-size:9.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--ink-3);font-weight:600}\r\n\r\n/* ---------- preset chips ---------- */\r\n.chips{display:flex;gap:7px;flex-wrap:wrap}\r\n.chip{\r\n  display:inline-flex;align-items:center;gap:6px;padding:8px 12px;border-radius:999px;\r\n  border:1px solid var(--line);background:var(--surface-2);font-size:11.5px;font-weight:500;color:var(--ink-2);\r\n  transition:.15s ease;\r\n}\r\n.chip:hover{border-color:var(--brand);color:var(--brand)}\r\n.chip.on{background:var(--brand-soft);border-color:var(--brand);color:var(--brand);box-shadow:inset 0 0 0 1px var(--brand)}\r\n.chip .e{font-size:13px}\r\n\r\n/* ---------- segmented ---------- */\r\n.seg{display:inline-flex;padding:3px;gap:3px;background:var(--surface-3);border-radius:11px;border:1px solid var(--line-2);flex-wrap:wrap}\r\n.seg button{\r\n  padding:7px 13px;border-radius:8px;font-size:11.5px;font-weight:500;color:var(--ink-2);transition:.15s ease;white-space:nowrap;\r\n}\r\n.seg button.on{background:var(--surface);color:var(--brand);box-shadow:var(--shadow-sm);font-weight:600}\r\n.seg.wide{display:flex;width:100%}\r\n.seg.wide button{flex:1}\r\n\r\n/* ---------- fields ---------- */\r\n.field{margin-bottom:13px}\r\n.field:last-child{margin-bottom:0}\r\n.field-top{display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin-bottom:6px}\r\n.field-top label{font-size:11.5px;color:var(--ink-2);font-weight:400}\r\n.field-top output{font-size:12px;font-weight:600;color:var(--brand);font-variant-numeric:tabular-nums}\r\ninput[type=range]{\r\n  -webkit-appearance:none;appearance:none;width:100%;height:4px;border-radius:99px;outline:none;\r\n  background:linear-gradient(90deg,var(--brand) var(--fill,50%),var(--line) var(--fill,50%));\r\n}\r\ninput[type=range]::-webkit-slider-thumb{\r\n  -webkit-appearance:none;width:16px;height:16px;border-radius:50%;background:#fff;border:4px solid var(--brand);\r\n  box-shadow:0 2px 6px rgba(16,32,64,.22);cursor:grab;\r\n}\r\ninput[type=range]::-webkit-slider-thumb:active{cursor:grabbing;transform:scale(1.06)}\r\ninput[type=range]::-moz-range-thumb{width:12px;height:12px;border-radius:50%;background:#fff;border:4px solid var(--brand)}\r\n.range-scale{display:flex;justify-content:space-between;font-size:9.5px;color:var(--ink-3);margin-top:4px;font-weight:300}\r\n\r\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:10px}\r\n.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}\r\n.num{display:flex;flex-direction:column;gap:4px}\r\n.num span{font-size:10.5px;color:var(--ink-3);font-weight:300}\r\n.num input,select.sel{\r\n  width:100%;padding:8px 10px;border-radius:9px;border:1px solid var(--line);background:var(--surface-2);\r\n  font-size:12.5px;font-weight:500;font-variant-numeric:tabular-nums;transition:.15s ease;\r\n}\r\n.num input:focus,select.sel:focus{outline:none;border-color:var(--brand);box-shadow:0 0 0 3px rgba(59,91,253,.14);background:var(--surface)}\r\nselect.sel{appearance:none;background-image:url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='10' height='6'><path d='M0 0l5 6 5-6z' fill='%238b98ac'/></svg>\");background-repeat:no-repeat;background-position:right 10px center;padding-right:26px}\r\n\r\n/* ---------- accordion ---------- */\r\ndetails.acc{border-top:1px solid var(--line-2)}\r\ndetails.acc:first-of-type{border-top:0}\r\ndetails.acc > summary{\r\n  list-style:none;display:flex;align-items:center;gap:8px;padding:12px 16px;font-size:11.5px;font-weight:600;\r\n  color:var(--ink-2);cursor:pointer;user-select:none;\r\n}\r\ndetails.acc > summary::-webkit-details-marker{display:none}\r\ndetails.acc > summary .caret{margin-left:auto;transition:.2s;color:var(--ink-3);font-size:10px}\r\ndetails.acc[open] > summary .caret{transform:rotate(180deg)}\r\ndetails.acc > summary:hover{color:var(--brand)}\r\ndetails.acc .acc-body{padding:2px 16px 16px}\r\n\r\n/* ---------- KPI ---------- */\r\n.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}\r\n.kpi{\r\n  position:relative;padding:14px 15px 13px;border-radius:var(--r-lg);border:1px solid var(--line);\r\n  background:var(--surface);box-shadow:var(--shadow-sm);overflow:hidden;min-width:0;\r\n}\r\n.kpi .k-label{font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:var(--ink-3);font-weight:600;display:flex;gap:5px;align-items:center}\r\n.kpi .k-val{font-size:clamp(17px,1.55vw,24px);font-weight:700;letter-spacing:-.02em;margin-top:6px;font-variant-numeric:tabular-nums;line-height:1.15;white-space:nowrap}\r\n.kpi .k-sub{font-size:10px;color:var(--ink-3);margin-top:4px;font-weight:300;min-height:14px}\r\n.kpi.hero{background:linear-gradient(135deg,#3b5bfd 0%,#4d6bff 45%,#0fb5a5 130%);border-color:transparent;color:#fff;box-shadow:0 14px 30px rgba(59,91,253,.32)}\r\n.kpi.hero .k-label,.kpi.hero .k-sub{color:rgba(255,255,255,.78)}\r\n.kpi.hero::after{content:\"\";position:absolute;right:-30px;top:-40px;width:120px;height:120px;border-radius:50%;background:rgba(255,255,255,.1)}\r\n.kpi[data-tone=\"ok\"] .k-val{color:var(--ok)}\r\n.kpi[data-tone=\"bad\"] .k-val{color:var(--bad)}\r\n.kpi[data-tone=\"warn\"] .k-val{color:var(--warn)}\r\n.kpi.hero .k-val{color:#fff}\r\n.kpi .badge{position:absolute;right:12px;top:12px;font-size:9px;padding:2px 7px;border-radius:999px;background:var(--surface-3);color:var(--ink-2);font-weight:600}\r\n.kpi.hero .badge{background:rgba(255,255,255,.2);color:#fff}\r\n\r\n/* ---------- views ---------- */\r\n.view[hidden]{display:none!important}\r\n.sec-title{font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-3);display:flex;align-items:center;gap:8px;margin-bottom:10px}\r\n.sec-title .line{flex:1;height:1px;background:var(--line-2)}\r\n\r\n/* ---------- cost bar ---------- */\r\n.cbar{display:flex;height:24px;border-radius:8px;overflow:hidden;background:var(--surface-3);box-shadow:inset 0 1px 3px rgba(0,0,0,.05)}\r\n.cbar i{display:block;height:100%;transition:width .35s ease}\r\n.cbar i:first-child{border-radius:8px 0 0 8px}\r\n.cbar i:last-child{border-radius:0 8px 8px 0}\r\n.legend{display:grid;grid-template-columns:repeat(auto-fit,minmax(148px,1fr));gap:8px 14px;margin-top:14px}\r\n.legend div{display:flex;align-items:center;gap:7px;font-size:11px;color:var(--ink-2)}\r\n.legend i{width:8px;height:8px;border-radius:3px;flex:0 0 auto}\r\n.legend b{margin-left:auto;font-weight:600;color:var(--ink);font-variant-numeric:tabular-nums}\r\n\r\n/* ---------- breakeven ---------- */\r\n.be-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}\r\n.be{padding:12px 13px;border-radius:var(--r-md);background:var(--surface-2);border:1px solid var(--line-2)}\r\n.be span{display:block;font-size:10px;color:var(--ink-3);font-weight:300}\r\n.be b{display:block;font-size:16px;font-weight:700;margin-top:3px;font-variant-numeric:tabular-nums}\r\n.be small{display:block;font-size:9.5px;color:var(--ink-3);margin-top:2px;font-weight:300}\r\n\r\n/* ---------- sensitivity ---------- */\r\n.sens{display:grid;grid-template-columns:repeat(5,1fr);gap:7px}\r\n.sens .cell{\r\n  padding:9px 8px;border-radius:var(--r-sm);border:1px solid var(--line-2);background:var(--surface-2);text-align:center;transition:.15s;\r\n}\r\n.sens .cell.on{border-color:var(--brand);background:var(--brand-soft)}\r\n.sens .cell em{display:block;font-style:normal;font-size:9.5px;color:var(--ink-3)}\r\n.sens .cell b{display:block;font-size:13px;font-weight:700;margin-top:2px;font-variant-numeric:tabular-nums}\r\n.sens .cell small{display:block;font-size:9px;color:var(--ink-3);margin-top:1px}\r\n\r\n/* ---------- chart ---------- */\r\n.chart-wrap{position:relative;height:268px}\r\n.chart-wrap canvas{width:100%;height:100%;display:block}\r\n\r\n/* ---------- tables ---------- */\r\n.tbl-wrap{overflow:auto;max-height:460px;border-radius:var(--r-md);border:1px solid var(--line-2)}\r\ntable{width:100%;border-collapse:collapse;font-size:11.5px;font-variant-numeric:tabular-nums}\r\nthead th{\r\n  position:sticky;top:0;background:var(--surface-3);color:var(--ink-2);font-weight:600;font-size:10px;\r\n  letter-spacing:.05em;text-transform:uppercase;text-align:right;padding:9px 11px;border-bottom:1px solid var(--line);white-space:nowrap;\r\n}\r\nthead th:first-child,tbody td:first-child{text-align:left}\r\ntbody td{padding:8px 11px;text-align:right;border-bottom:1px solid var(--line-2);color:var(--ink-2);white-space:nowrap}\r\ntbody tr:last-child td{border-bottom:0}\r\ntbody tr:hover td{background:var(--surface-2)}\r\ntd.pos{color:var(--ok);font-weight:600}\r\ntd.neg{color:var(--bad);font-weight:600}\r\ntd.em{color:var(--ink);font-weight:600}\r\n\r\n/* ---------- loan ---------- */\r\n.loan-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px}\r\n.lc{padding:12px 13px;border-radius:var(--r-md);border:1px solid var(--line-2);background:var(--surface-2)}\r\n.lc span{display:block;font-size:10px;color:var(--ink-3);font-weight:300}\r\n.lc b{display:block;font-size:15px;font-weight:700;margin-top:3px;font-variant-numeric:tabular-nums}\r\n.lc.hl{background:linear-gradient(135deg,rgba(59,91,253,.1),rgba(15,181,165,.1));border-color:rgba(59,91,253,.3)}\r\n.note{\r\n  display:flex;gap:9px;padding:11px 13px;border-radius:var(--r-md);font-size:11px;line-height:1.6;\r\n  background:var(--warn-soft);border:1px solid rgba(185,119,8,.25);color:var(--ink-2);\r\n}\r\n.note.ok{background:var(--ok-soft);border-color:rgba(14,159,110,.25)}\r\n.note.bad{background:var(--bad-soft);border-color:rgba(214,61,61,.25)}\r\n.note b{color:var(--ink)}\r\n.empty{padding:26px 16px;text-align:center;color:var(--ink-3);font-size:11.5px}\r\n\r\n/* ---------- matrix ---------- */\r\n.matrix{overflow:auto}\r\n.matrix table{font-size:10.5px}\r\n.matrix th,.matrix td{padding:6px 8px;text-align:center}\r\n.matrix td button{\r\n  width:100%;padding:5px 2px;border-radius:6px;font-size:10.5px;font-variant-numeric:tabular-nums;color:var(--ink-2);\r\n  border:1px solid transparent;transition:.12s;\r\n}\r\n.matrix td button:hover{background:var(--brand-soft);color:var(--brand)}\r\n.matrix td button.on{background:var(--brand);color:#fff;font-weight:600;box-shadow:0 4px 10px rgba(59,91,253,.3)}\r\n.matrix th.corner{background:transparent;border:0}\r\n.matrix tbody th{\r\n  position:static;background:transparent;text-transform:none;letter-spacing:0;font-size:10.5px;\r\n  color:var(--ink-3);padding:6px 4px;border:0;font-weight:500;white-space:nowrap;\r\n}\r\n\r\n/* ---------- notes ---------- */\r\n.notes h3{font-size:12.5px;margin:0 0 7px;font-weight:600}\r\n.notes h4{font-size:11.5px;margin:14px 0 5px;font-weight:600;color:var(--ink-2)}\r\n.notes p,.notes li{font-size:11.5px;color:var(--ink-2);line-height:1.75;font-weight:300}\r\n.notes ul{margin:0;padding-left:18px}\r\n.notes code{\r\n  font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:11px;background:var(--surface-3);\r\n  padding:1.5px 6px;border-radius:5px;color:var(--brand);border:1px solid var(--line-2);\r\n}\r\n.formula{\r\n  padding:11px 13px;border-radius:var(--r-md);background:var(--surface-2);border:1px solid var(--line-2);\r\n  font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:11px;line-height:2;color:var(--ink-2);overflow:auto;\r\n}\r\n.src{display:flex;gap:8px;align-items:flex-start;padding:9px 0;border-bottom:1px dashed var(--line-2);font-size:11px;color:var(--ink-2);font-weight:300}\r\n.src:last-child{border-bottom:0}\r\n.src b{color:var(--ink);font-weight:600}\r\n\r\n/* ---------- toast ---------- */\r\n.toast{\r\n  position:fixed;left:50%;bottom:26px;transform:translate(-50%,18px);opacity:0;pointer-events:none;\r\n  background:#0d1526;color:#fff;padding:10px 18px;border-radius:999px;font-size:12px;z-index:90;\r\n  box-shadow:0 12px 30px rgba(0,0,0,.35);transition:.25s ease;\r\n}\r\n.toast.on{opacity:1;transform:translate(-50%,0)}\r\n\r\n/* ---------- verdict ---------- */\r\n.verdict{\r\n  display:grid;grid-template-columns:1fr auto;gap:18px;align-items:center;padding:16px 18px;border-radius:var(--r-lg);\r\n  border:1px solid rgba(59,91,253,.22);background:linear-gradient(135deg,rgba(59,91,253,.07),rgba(15,181,165,.07));\r\n  box-shadow:var(--shadow-sm);\r\n}\r\n.verdict.bad{border-color:rgba(214,61,61,.28);background:linear-gradient(135deg,rgba(214,61,61,.08),rgba(214,61,61,.02))}\r\n.verdict.bad .v-tag{background:var(--bad-soft);color:var(--bad)}\r\n.v-tag{display:inline-block;padding:2px 9px;border-radius:999px;background:var(--brand-soft);color:var(--brand);font-size:9.5px;font-weight:600;letter-spacing:.06em}\r\n.verdict p{font-size:12.5px;line-height:1.85;color:var(--ink-2);margin-top:7px}\r\n.verdict p b{color:var(--ink);font-weight:600}\r\n.v-chips{display:flex;gap:20px;align-items:center;padding-left:18px;border-left:1px solid var(--line)}\r\n.v-chips span{display:block;font-size:9.5px;color:var(--ink-3)}\r\n.v-chips b{display:block;font-size:15px;font-weight:700;margin-top:2px;font-variant-numeric:tabular-nums;white-space:nowrap}\r\n\r\n/* ---------- compare ---------- */\r\n.cmp{display:grid;grid-template-columns:1fr 1fr;gap:12px}\r\n.cmp .col{border:1px solid var(--line-2);border-radius:var(--r-md);background:var(--surface-2);padding:13px}\r\n.cmp .col.on{border-color:var(--brand);background:var(--brand-soft)}\r\n.cmp h4{margin:0 0 8px;font-size:11.5px;font-weight:600;display:flex;align-items:center;gap:6px}\r\n.cmp h4 small{margin-left:auto;font-size:9px;font-weight:500;color:var(--brand);background:var(--surface);border:1px solid var(--line);padding:1px 7px;border-radius:999px}\r\n.cmp .row{display:flex;justify-content:space-between;gap:10px;font-size:11px;padding:5px 0;border-bottom:1px dashed var(--line-2);color:var(--ink-2)}\r\n.cmp .row:last-child{border-bottom:0}\r\n.cmp .row b{font-variant-numeric:tabular-nums;color:var(--ink);font-weight:600;white-space:nowrap}\r\n\r\n/* ---------- advanced ---------- */\r\ndetails.acc.sub{border-top:1px dashed var(--line-2);margin-top:6px}\r\ndetails.acc.sub > summary{font-size:10.5px;font-weight:500;padding:8px 0;color:var(--ink-3)}\r\n\r\n/* ---------- responsive ---------- */\r\n@media (max-width:1180px){\r\n  .app{grid-template-columns:1fr}\r\n  .kpis{grid-template-columns:repeat(2,1fr)}\r\n  .input-panel{position:static!important;max-height:none!important}\r\n}\r\n@media (max-width:640px){\r\n  .app{padding:12px 12px 60px;gap:12px}\r\n  .topbar{padding:9px 13px;gap:9px}\r\n  .brand small{display:none}\r\n  .top-actions .pill{display:none}\r\n  .kpi .k-val{font-size:20px}\r\n  .verdict{grid-template-columns:1fr}\r\n  .v-chips{padding-left:0;border-left:0;border-top:1px solid var(--line);padding-top:12px;justify-content:space-between}\r\n  .cmp{grid-template-columns:1fr}\r\n  .be-grid{grid-template-columns:1fr 1fr}\r\n  .sens{grid-template-columns:repeat(3,1fr)}\r\n  .grid3{grid-template-columns:1fr 1fr}\r\n  .card-body{padding:13px}\r\n  .chart-wrap{height:220px}\r\n}\r\n@media print{\r\n  .topbar,.input-panel,.seg,.btn,.toast{display:none!important}\r\n  body{background:#fff}\r\n  .app{display:block;padding:0;max-width:none}\r\n  .card{box-shadow:none;break-inside:avoid;margin-bottom:10px}\r\n  .tbl-wrap{max-height:none;overflow:visible}\r\n}\r\n</style>\r\n<style id=\"ux2\">\r\n/* ============================================================\r\n   UX2 — premium glass layer (aesthetics only, no layout changes)\r\n   ============================================================ */\r\n:root{\r\n  --brand:#4f46e5; --brand-2:#0d9488; --brand-3:#8b5cf6;\r\n  --brand-soft:rgba(79,70,229,.10);\r\n  --surface:rgba(255,255,255,.90);\r\n  --surface-2:rgba(255,255,255,.74);\r\n  --surface-3:rgba(238,243,252,.92);\r\n  --line:rgba(18,32,74,.13);\r\n  --line-2:rgba(18,32,74,.08);\r\n  --ink-3:#6b7791;\r\n  --shadow:0 28px 64px -34px rgba(10,22,55,.55);\r\n  --shadow-sm:0 14px 32px -24px rgba(10,22,55,.62);\r\n  --r-lg:22px; --r-md:14px; --r-sm:10px;\r\n}\r\n[data-theme=\"dark\"]{\r\n  --brand:#818cf8; --brand-2:#2dd4bf; --brand-3:#a78bfa;\r\n  --brand-soft:rgba(129,140,248,.14);\r\n  --surface:rgba(21,30,50,.88);\r\n  --surface-2:rgba(27,38,62,.72);\r\n  --surface-3:rgba(33,46,73,.85);\r\n  --line:rgba(125,155,225,.18);\r\n  --line-2:rgba(125,155,225,.10);\r\n  --ink-3:#8391ad;\r\n  --shadow:0 30px 70px -34px rgba(0,0,0,.9);\r\n  --shadow-sm:0 14px 34px -22px rgba(0,0,0,.95);\r\n}\r\n\r\n/* --- ambient background --- */\r\nbody{\r\n  background:\r\n    radial-gradient(1000px 620px at 8% -12%, rgba(79,70,229,.20), transparent 62%),\r\n    radial-gradient(900px 560px at 96% -6%, rgba(13,148,136,.17), transparent 58%),\r\n    radial-gradient(800px 600px at 52% 112%, rgba(139,92,246,.13), transparent 62%),\r\n    var(--bg);\r\n  background-attachment:fixed;\r\n}\r\nbody::after{\r\n  content:\"\"; position:fixed; inset:-10%; z-index:-1; pointer-events:none;\r\n  background:\r\n    radial-gradient(closest-side, rgba(79,70,229,.16), transparent) 12% 22%/44vmax 44vmax no-repeat,\r\n    radial-gradient(closest-side, rgba(13,148,136,.14), transparent) 88% 68%/40vmax 40vmax no-repeat;\r\n  animation:drift 26s ease-in-out infinite alternate;\r\n}\r\n@keyframes drift{\r\n  from{transform:translate3d(0,0,0) scale(1)}\r\n  to{transform:translate3d(-2.5%,2%,0) scale(1.06)}\r\n}\r\n\r\n/* --- top bar --- */\r\n.topbar{\r\n  background:color-mix(in srgb, var(--surface) 78%, transparent);\r\n  backdrop-filter:blur(24px) saturate(180%);\r\n  border-bottom:1px solid var(--line);\r\n  box-shadow:0 10px 30px -26px rgba(10,22,55,.5);\r\n}\r\n.mark{\r\n  background:linear-gradient(140deg,var(--brand),var(--brand-3) 55%,var(--brand-2));\r\n  box-shadow:0 10px 24px -8px rgba(79,70,229,.65), inset 0 1px 0 rgba(255,255,255,.35);\r\n}\r\n.brand strong{letter-spacing:-.015em}\r\n.pill{\r\n  background:color-mix(in srgb, var(--surface) 70%, transparent);\r\n  backdrop-filter:blur(12px);\r\n  border-color:var(--line);\r\n}\r\n\r\n/* --- buttons --- */\r\n.btn{\r\n  background:color-mix(in srgb, var(--surface) 74%, transparent);\r\n  border-color:var(--line);\r\n  border-radius:12px;\r\n  transition:transform .18s cubic-bezier(.2,.8,.3,1), box-shadow .18s, border-color .18s, color .18s;\r\n}\r\n.btn:hover{transform:translateY(-1px);box-shadow:0 12px 24px -14px rgba(79,70,229,.55);border-color:color-mix(in srgb, var(--brand) 55%, transparent)}\r\n.btn:active{transform:translateY(0) scale(.985)}\r\n.btn.solid{\r\n  background:linear-gradient(135deg,var(--brand),var(--brand-3) 52%,var(--brand-2));\r\n  background-size:180% 180%;\r\n  border-color:transparent; color:#fff;\r\n  box-shadow:0 14px 30px -14px rgba(79,70,229,.75), inset 0 1px 0 rgba(255,255,255,.28);\r\n  animation:sheen 9s ease infinite;\r\n}\r\n@keyframes sheen{0%,100%{background-position:0% 50%}50%{background-position:100% 50%}}\r\n\r\n/* --- cards --- */\r\n.card{\r\n  background:var(--surface);\r\n  border:1px solid var(--line);\r\n  border-radius:var(--r-lg);\r\n  box-shadow:var(--shadow-sm);\r\n  transition:box-shadow .25s ease, transform .25s ease, border-color .25s ease;\r\n  animation:rise .5s cubic-bezier(.2,.8,.3,1) both;\r\n}\r\n.card:hover{box-shadow:var(--shadow);border-color:color-mix(in srgb, var(--brand) 22%, var(--line))}\r\n@keyframes rise{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}\r\n.card-head{border-bottom:1px solid var(--line-2)}\r\n.card-head h2{letter-spacing:.005em;font-size:13px;font-weight:600}\r\n.topbar::after{\r\n  content:\"\"; position:absolute; left:0; right:0; bottom:-1px; height:1px; pointer-events:none;\r\n  background:linear-gradient(90deg, transparent, rgba(79,70,229,.55), rgba(13,148,136,.55), transparent);\r\n}\r\n\r\n/* --- KPI --- */\r\n.kpi{\r\n  background:var(--surface);\r\n  border:1px solid var(--line);\r\n  border-radius:var(--r-lg);\r\n  box-shadow:var(--shadow-sm);\r\n  transition:transform .25s cubic-bezier(.2,.8,.3,1), box-shadow .25s;\r\n}\r\n.kpi:hover{transform:translateY(-2px);box-shadow:var(--shadow)}\r\n.kpi.hero{\r\n  background:\r\n    radial-gradient(120% 130% at 100% 0%, rgba(255,255,255,.26), transparent 46%),\r\n    linear-gradient(135deg,#4f46e5 0%,#6366f1 42%,#0d9488 118%);\r\n  background-size:160% 160%;\r\n  border-color:rgba(255,255,255,.22);\r\n  box-shadow:0 22px 44px -20px rgba(79,70,229,.75), inset 0 1px 0 rgba(255,255,255,.3);\r\n  animation:heroShift 12s ease-in-out infinite alternate;\r\n}\r\n@keyframes heroShift{from{background-position:0% 0%}to{background-position:100% 100%}}\r\n.kpi.hero::before{\r\n  content:\"\"; position:absolute; inset:0; border-radius:inherit; pointer-events:none;\r\n  background:radial-gradient(240px circle at var(--mx,70%) var(--my,0%), rgba(255,255,255,.22), transparent 65%);\r\n  transition:background .2s;\r\n}\r\n.kpi .ring{\r\n  position:absolute; right:12px; top:12px; width:42px; height:42px; border-radius:50%;\r\n  background:conic-gradient(#fff calc(var(--v,0) * 1turn), rgba(255,255,255,.22) 0);\r\n  -webkit-mask:radial-gradient(farthest-side, transparent calc(100% - 6px), #000 calc(100% - 5px));\r\n  mask:radial-gradient(farthest-side, transparent calc(100% - 6px), #000 calc(100% - 5px));\r\n  transition:background .5s ease;\r\n}\r\n.kpi .k-val{letter-spacing:-.03em}\r\n.kpi.hero .k-sub{padding-right:0}\r\n.kpi.hero .k-label{padding-right:50px}\r\n.kpi.flash .k-val{animation:flash .5s cubic-bezier(.2,.8,.3,1)}\r\n@keyframes flash{\r\n  0%{box-shadow:0 0 0 0 rgba(79,70,229,.35)}\r\n  60%{box-shadow:0 0 0 12px rgba(79,70,229,0)}\r\n  100%{box-shadow:0 0 0 0 rgba(79,70,229,0)}\r\n}\r\n.kpi.hero .k-val{text-shadow:0 2px 14px rgba(0,0,0,.18)}\r\n\r\n/* --- segmented control --- */\r\n.seg{\r\n  position:relative; border:1px solid var(--line);\r\n  background:color-mix(in srgb, var(--surface-3) 85%, transparent);\r\n}\r\n.seg button{position:relative; isolation:isolate; border-radius:9px; transition:color .2s}\r\n.seg button::before{\r\n  content:\"\"; position:absolute; inset:0; border-radius:9px; z-index:-1;\r\n  background:linear-gradient(135deg, rgba(79,70,229,.18), rgba(13,148,136,.16));\r\n  border:1px solid color-mix(in srgb, var(--brand) 32%, transparent);\r\n  box-shadow:0 8px 18px -12px rgba(79,70,229,.7);\r\n  opacity:0; transform:scale(.9); transition:opacity .22s, transform .28s cubic-bezier(.34,1.4,.64,1);\r\n}\r\n.seg button.on::before{opacity:1;transform:scale(1)}\r\n.seg button.on{background:transparent!important;box-shadow:none!important}\r\n\r\n/* --- chips --- */\r\n.chip{\r\n  background:color-mix(in srgb, var(--surface-2) 80%, transparent);\r\n  border-color:var(--line);\r\n  transition:transform .18s cubic-bezier(.2,.8,.3,1), box-shadow .18s, border-color .18s, color .18s, background .18s;\r\n}\r\n.chip:hover{transform:translateY(-1px);box-shadow:0 10px 20px -16px rgba(79,70,229,.7)}\r\n.chip.on{\r\n  background:linear-gradient(135deg, rgba(79,70,229,.16), rgba(13,148,136,.14));\r\n  border-color:color-mix(in srgb, var(--brand) 55%, transparent);\r\n  color:var(--brand); box-shadow:0 10px 22px -16px rgba(79,70,229,.8), inset 0 0 0 1px transparent;\r\n}\r\n\r\n/* --- inputs --- */\r\n.num input, select.sel{\r\n  background:color-mix(in srgb, var(--surface-2) 88%, transparent);\r\n  border-color:var(--line);\r\n  border-radius:10px;\r\n  transition:border-color .18s, box-shadow .18s, background .18s;\r\n}\r\n.num input:hover, select.sel:hover{border-color:color-mix(in srgb, var(--brand) 28%, var(--line))}\r\n.num input:focus, select.sel:focus{\r\n  border-color:color-mix(in srgb, var(--brand) 60%, transparent);\r\n  box-shadow:0 0 0 4px color-mix(in srgb, var(--brand) 14%, transparent);\r\n}\r\ninput[type=range]{height:6px}\r\ninput[type=range]::-webkit-slider-thumb{\r\n  width:17px;height:17px;border-width:4px;\r\n  box-shadow:0 3px 10px rgba(79,70,229,.42), 0 0 0 4px color-mix(in srgb, var(--brand) 14%, transparent);\r\n  transition:transform .15s, box-shadow .15s;\r\n}\r\ninput[type=range]::-webkit-slider-thumb:hover{transform:scale(1.12);box-shadow:0 3px 14px rgba(79,70,229,.6), 0 0 0 6px color-mix(in srgb, var(--brand) 16%, transparent)}\r\ndetails.acc > summary{border-radius:10px;transition:color .18s}\r\ndetails.acc > summary:hover{color:var(--brand)}\r\n\r\n/* --- verdict / compare / small cards --- */\r\n.verdict{\r\n  background:\r\n    radial-gradient(120% 140% at 0% 0%, rgba(79,70,229,.16), transparent 55%),\r\n    radial-gradient(120% 140% at 100% 100%, rgba(13,148,136,.16), transparent 55%),\r\n    var(--surface);\r\n  backdrop-filter:blur(22px) saturate(170%);\r\n  border-color:color-mix(in srgb, var(--brand) 26%, transparent);\r\n  box-shadow:var(--shadow-sm);\r\n}\r\n.verdict.bad{\r\n  background:\r\n    radial-gradient(120% 140% at 0% 0%, rgba(214,61,61,.14), transparent 55%),\r\n    var(--surface);\r\n  border-color:rgba(214,61,61,.28);\r\n}\r\n.cmp .col{background:color-mix(in srgb, var(--surface-2) 70%, transparent);border-color:var(--line);transition:border-color .2s, box-shadow .2s}\r\n.cmp .col.on{box-shadow:0 16px 34px -26px rgba(79,70,229,.8)}\r\n.be{\r\n  background:linear-gradient(160deg, rgba(79,70,229,.06), rgba(13,148,136,.05));\r\n  border-color:color-mix(in srgb, var(--brand) 16%, var(--line));\r\n}\r\n.be span{color:var(--ink-2);font-weight:400}\r\n.be b{font-size:19px;letter-spacing:-.02em}\r\n.be small{color:var(--ink-3)}\r\n.num span{color:var(--ink-2)}\r\n.range-scale{color:var(--ink-3)}\r\n.field-top output{font-weight:600}\r\n.sens .cell{background:color-mix(in srgb, var(--surface-2) 72%, transparent);border-color:var(--line);transition:transform .18s, border-color .18s, background .18s}\r\n.sens .cell:hover{transform:translateY(-2px);border-color:color-mix(in srgb, var(--brand) 40%, var(--line))}\r\n.sens .cell.on{background:linear-gradient(135deg, rgba(79,70,229,.16), rgba(13,148,136,.12));border-color:color-mix(in srgb, var(--brand) 45%, transparent)}\r\n.legend i{box-shadow:0 0 0 2px color-mix(in srgb, currentColor 0%, transparent)}\r\n.cbar{box-shadow:inset 0 1px 4px rgba(10,22,55,.12);background:color-mix(in srgb, var(--surface-3) 80%, transparent)}\r\n\r\n/* --- tables & matrix --- */\r\n.tbl-wrap{border-color:var(--line);background:color-mix(in srgb, var(--surface) 60%, transparent)}\r\nthead th{background:color-mix(in srgb, var(--surface-3) 92%, transparent)}\r\ntbody tr:hover td{background:color-mix(in srgb, var(--brand) 5%, transparent)}\r\n.matrix td button{border-radius:8px;transition:transform .14s, background .14s, color .14s}\r\n.matrix td button:hover{transform:scale(1.04)}\r\n.matrix td button.on{background:linear-gradient(135deg,var(--brand),var(--brand-2));box-shadow:0 8px 18px -10px rgba(79,70,229,.8)}\r\n\r\n/* --- chart tooltip --- */\r\n.chart-tip{\r\n  position:absolute; z-index:6; pointer-events:none; opacity:0;\r\n  transform:translate(-50%,-130%); transition:opacity .13s ease;\r\n  padding:7px 11px; border-radius:10px; white-space:nowrap;\r\n  background:color-mix(in srgb, #0b1224 88%, transparent);\r\n  border:1px solid rgba(255,255,255,.16);\r\n  color:#fff; font-size:10.5px; line-height:1.5;\r\n  box-shadow:0 16px 30px -18px rgba(0,0,0,.8);\r\n  backdrop-filter:blur(10px);\r\n}\r\n.chart-tip.on{opacity:1}\r\n.chart-tip b{color:#a5b4fc;font-weight:600}\r\n\r\n/* --- toast --- */\r\n.toast{\r\n  background:color-mix(in srgb, #0b1224 86%, transparent);\r\n  border:1px solid rgba(255,255,255,.14);\r\n  backdrop-filter:blur(14px);\r\n  box-shadow:0 20px 40px -20px rgba(0,0,0,.7);\r\n}\r\n\r\n/* --- scrollbars --- */\r\n.input-panel::-webkit-scrollbar,.tbl-wrap::-webkit-scrollbar,.matrix::-webkit-scrollbar,.formula::-webkit-scrollbar{width:8px;height:8px}\r\n.input-panel::-webkit-scrollbar-thumb,.tbl-wrap::-webkit-scrollbar-thumb,.matrix::-webkit-scrollbar-thumb,.formula::-webkit-scrollbar-thumb{\r\n  background:color-mix(in srgb, var(--ink-3) 35%, transparent);border-radius:99px\r\n}\r\n.input-panel::-webkit-scrollbar-track,.tbl-wrap::-webkit-scrollbar-track,.matrix::-webkit-scrollbar-track,.formula::-webkit-scrollbar-track{background:transparent}\r\n\r\n/* --- motion preferences --- */\r\n@media (prefers-reduced-motion: reduce){\r\n  *,*::before,*::after{animation-duration:.001ms!important;animation-iteration-count:1!important;transition-duration:.001ms!important}\r\n  body::after{display:none}\r\n}\r\n\r\n/* keep mobile layout rules from the base sheet winning over the glass layer */\r\n@media (max-width:1180px){\r\n  .topbar{backdrop-filter:blur(18px) saturate(150%)}\r\n  .app{grid-template-columns:minmax(0,1fr)}\r\n  .app > *{min-width:0}\r\n  .stack,.card,.card-body{min-width:0}\r\n}\r\n\r\n/* ---------- embed mode (used inside Prospect Intelligence iframe) ---------- */\r\nhtml.embed .topbar{display:none}\r\nhtml.embed body{background:transparent}\r\nhtml.embed .app{padding:14px 14px 26px;max-width:none;gap:14px;grid-template-columns:minmax(320px,360px) minmax(0,1fr)}\r\nhtml.embed .kpis{grid-template-columns:repeat(4,minmax(0,1fr))}\r\nhtml.embed .verdict{grid-template-columns:1fr;gap:12px}\r\nhtml.embed .v-chips{padding-left:0;border-left:0;border-top:1px solid var(--line);padding-top:11px;justify-content:space-between}\r\nhtml.embed .input-panel{top:8px!important;max-height:calc(100vh - 20px)!important}\r\nhtml.embed .verdict{border-color:var(--line)}\r\n@media (max-width:1180px){\r\n  html.embed .input-panel{position:sticky!important;max-height:calc(100vh - 20px)!important;overflow:auto}\r\n}\r\n@media (max-width:900px){\r\n  html.embed .app{grid-template-columns:minmax(0,1fr)}\r\n  html.embed .kpis{grid-template-columns:repeat(2,minmax(0,1fr))}\r\n  html.embed .input-panel{position:static!important;max-height:none!important;overflow:visible}\r\n}\r\n@media (max-width:640px){\r\n  .num input, select.sel{min-width:0}\r\n  .seg button{flex:1 1 auto}\r\n  .topbar{flex-wrap:wrap;row-gap:8px}\r\n  .brand{flex:0 0 auto}\r\n  .brand strong{white-space:nowrap;font-size:13.5px}\r\n  .top-actions{margin-left:auto}\r\n  .btn{padding:7px 11px;font-size:11.5px}\r\n  .btn.icon{width:34px;height:34px}\r\n}\r\n</style>\r\n</head>\r\n<body>\r\n\r\n<header class=\"topbar\">\r\n  <div class=\"brand\">\r\n    <div class=\"mark\">ROI</div>\r\n    <div>\r\n      <strong>ROI Studio</strong>\r\n      <small>วิเคราะห์การลงทุน · ค่างวด · กระแสเงินสด</small>\r\n    </div>\r\n  </div>\r\n  <div class=\"top-actions\">\r\n    <span class=\"pill\">สินทรัพย์: <b id=\"topMachine\">ตู้กดน้ำด่าง</b></span>\r\n    <span class=\"pill\">กระแสเงินสด: <b id=\"topCash\">—</b></span>\r\n    <button class=\"btn\" id=\"btnCopy\" type=\"button\">คัดลอกข้อความนำเสนอ</button>\r\n    <button class=\"btn\" id=\"btnPrint\" type=\"button\">พิมพ์ / PDF</button>\r\n    <button class=\"btn icon\" id=\"btnTheme\" type=\"button\" title=\"สลับโหมดสว่าง/มืด\" aria-label=\"สลับโหมดสว่าง/มืด\">◐</button>\r\n  </div>\r\n</header>\r\n\r\n<div class=\"app\">\r\n\r\n  <!-- ============ INPUT PANEL ============ -->\r\n  <aside class=\"panel input-panel\" style=\"position:sticky;top:72px;max-height:calc(100vh - 88px);overflow:auto;border-radius:18px\">\r\n    <div class=\"card\" style=\"overflow:hidden\">\r\n\r\n      <div class=\"card-head\">\r\n        <h2><span class=\"eyebrow\" style=\"letter-spacing:.1em\">ตัวแปร</span></h2>\r\n        <span class=\"hint\">แก้ไขแล้วผลลัพธ์อัปเดตทันที</span>\r\n      </div>\r\n\r\n      <div class=\"card-body\" style=\"padding-bottom:10px\">\r\n        <div class=\"field\">\r\n          <div class=\"field-top\"><label>เลือกสินทรัพย์</label></div>\r\n          <div class=\"chips\" id=\"presetChips\">\r\n            <button class=\"chip on\" data-preset=\"alkaline\" type=\"button\"><span class=\"e\">💧</span>ตู้กดน้ำด่าง</button>\r\n            <button class=\"chip\" data-preset=\"ice\" type=\"button\"><span class=\"e\">❄️</span>ตู้ผลิตน้ำแข็ง</button>\r\n            <button class=\"chip\" data-preset=\"coffee\" type=\"button\"><span class=\"e\">☕</span>ตู้กาแฟ 10 บาท</button>\r\n            <button class=\"chip\" data-preset=\"laundry\" type=\"button\"><span class=\"e\">🧺</span>เครื่องซักผ้า</button>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"field\" style=\"margin-bottom:0\">\r\n          <div class=\"field-top\"><label>ระดับยอดขายที่ใช้ประเมิน</label><output id=\"scenOut\">ตามเป้า</output></div>\r\n          <div class=\"seg wide\" id=\"scenarioSeg\">\r\n            <button data-scen=\"low\" type=\"button\">ต่ำกว่าเป้า 30%</button>\r\n            <button data-scen=\"base\" class=\"on\" type=\"button\">ตามเป้า</button>\r\n            <button data-scen=\"high\" type=\"button\">สูงกว่าเป้า 30%</button>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- 1. investment -->\r\n      <details class=\"acc\" open>\r\n        <summary>💵 เงินลงทุน &amp; สมมติฐานการวิเคราะห์ <span class=\"caret\">▾</span></summary>\r\n        <div class=\"acc-body\">\r\n          <div class=\"num\" style=\"margin-bottom:10px\">\r\n            <span>ราคาเครื่อง / ราคาลงทุน (บาท)</span>\r\n            <input type=\"number\" id=\"price\" value=\"45000\" min=\"0\" step=\"500\" inputmode=\"numeric\">\r\n          </div>\r\n\r\n          <!-- model reference (ทุกสินค้า) + BOQ เฉพาะเครื่องซักผ้า -->\r\n          <div id=\"modelBlock\" hidden style=\"margin-bottom:10px\">\r\n            <label class=\"num\" style=\"margin-bottom:8px\"><span id=\"modelLabel\">รุ่นสินค้าอ้างอิง (ราคาเงินสด)</span>\r\n              <select class=\"sel\" id=\"modelSel\"></select>\r\n            </label>\r\n            <div id=\"installBlock\" hidden>\r\n              <div class=\"num\"><span>ค่าติดตั้ง / เตรียมพื้นที่ (BOQ)</span>\r\n                <input type=\"number\" id=\"install\" value=\"6010\" min=\"0\" step=\"100\">\r\n              </div>\r\n              <div class=\"chips\" style=\"margin-top:7px\" id=\"boqChips\">\r\n                <button class=\"chip\" type=\"button\" data-n=\"1\">1 เครื่อง</button>\r\n                <button class=\"chip\" type=\"button\" data-n=\"2\">2</button>\r\n                <button class=\"chip\" type=\"button\" data-n=\"3\">3</button>\r\n                <button class=\"chip\" type=\"button\" data-n=\"4\">4</button>\r\n                <button class=\"chip\" type=\"button\" data-n=\"5\">5</button>\r\n              </div>\r\n            </div>\r\n          </div>\r\n          <p id=\"investHint\" style=\"font-size:9.5px;color:var(--ink-3);margin:-4px 0 10px;font-weight:300\"></p>\r\n\r\n          <div class=\"grid2\">\r\n            <label class=\"num\"><span>ระยะเวลาประเมิน (ปี)</span>\r\n              <select class=\"sel\" id=\"years\">\r\n                <option value=\"3\">3 ปี</option>\r\n                <option value=\"5\" selected>5 ปี</option>\r\n                <option value=\"7\">7 ปี</option>\r\n                <option value=\"10\">10 ปี</option>\r\n              </select>\r\n            </label>\r\n            <label class=\"num\"><span>อัตราคิดลด (NPV) %/ปี</span>\r\n              <input type=\"number\" id=\"discount\" value=\"8\" min=\"0\" max=\"40\" step=\"0.5\">\r\n            </label>\r\n          </div>\r\n          <details class=\"acc sub\">\r\n            <summary>ขั้นสูง: มูลค่าซาก &amp; อัตราคิดลด <span class=\"caret\">▾</span></summary>\r\n            <div class=\"acc-body\" style=\"padding:0\">\r\n              <label class=\"num\"><span>มูลค่าซากเมื่อสิ้นสุดโครงการ (บาท)</span>\r\n                <input type=\"number\" id=\"salvage\" value=\"0\" min=\"0\" step=\"1000\">\r\n              </label>\r\n              <p style=\"font-size:9.5px;color:var(--ink-3);margin:6px 0 0;font-weight:300\">\r\n                ใช้เฉพาะการคำนวณ NPV/IRR ไม่กระทบกำไรและระยะเวลาคืนทุน\r\n              </p>\r\n            </div>\r\n          </details>\r\n        </div>\r\n      </details>\r\n\r\n      <!-- 2. sales -->\r\n      <details class=\"acc\" open>\r\n        <summary>📈 ยอดขาย &amp; ราคาต่อหน่วย <span class=\"caret\">▾</span></summary>\r\n        <div class=\"acc-body\">\r\n          <div class=\"field\">\r\n            <div class=\"field-top\"><label for=\"qty\">ปริมาณขายต่อวัน</label><output id=\"qtyOut\">100 ลิตร</output></div>\r\n            <input type=\"range\" id=\"qty\" min=\"0\" max=\"400\" step=\"1\" value=\"100\">\r\n            <div class=\"range-scale\"><span>0</span><span>จุดคุ้มทุน <b id=\"beInline\">—</b></span><span id=\"qtyMaxOut\">400</span></div>\r\n          </div>\r\n          <div class=\"field\" style=\"margin-bottom:0\">\r\n            <div class=\"field-top\"><label for=\"unitPrice\">ราคาขายต่อหน่วย</label><output id=\"priceOut\">5.00 บาท</output></div>\r\n            <input type=\"range\" id=\"unitPrice\" min=\"1\" max=\"10\" step=\"0.5\" value=\"5\">\r\n            <div class=\"range-scale\"><span id=\"unitMinOut\">1 บาท</span><span id=\"unitMaxOut\">10 บาท</span></div>\r\n          </div>\r\n        </div>\r\n      </details>\r\n\r\n      <!-- 3. costs -->\r\n      <details class=\"acc\">\r\n        <summary>🧾 ต้นทุนดำเนินงาน <span class=\"caret\">▾</span></summary>\r\n        <div class=\"acc-body\">\r\n          <div class=\"field\">\r\n            <div class=\"field-top\"><label for=\"qrShare\">สัดส่วนลูกค้าจ่าย QR</label><output id=\"qrShareOut\">60%</output></div>\r\n            <input type=\"range\" id=\"qrShare\" min=\"0\" max=\"100\" step=\"5\" value=\"60\">\r\n          </div>\r\n          <div class=\"grid2\">\r\n            <label class=\"num\"><span>ค่าธรรมเนียม QR (%/ยอด)</span><input type=\"number\" id=\"qrFee\" value=\"1\" min=\"0\" max=\"10\" step=\"0.1\"></label>\r\n            <label class=\"num\"><span>ต้นทุนวัตถุดิบ (บาท/หน่วย)</span><input type=\"number\" id=\"rawCost\" value=\"0\" min=\"0\" step=\"0.5\"></label>\r\n          </div>\r\n          <div class=\"grid2\" style=\"margin-top:10px\">\r\n            <label class=\"num\"><span>กำลังไฟ (kW)</span><input type=\"number\" id=\"elecKW\" value=\"0.15\" min=\"0\" step=\"0.01\"></label>\r\n            <label class=\"num\"><span>ชั่วโมงทำงาน/วัน</span><input type=\"number\" id=\"elecHours\" value=\"12\" min=\"0\" max=\"24\" step=\"1\"></label>\r\n            <label class=\"num\"><span>ค่าไฟ (บาท/หน่วย)</span><input type=\"number\" id=\"elecRate\" value=\"4\" min=\"0\" step=\"0.1\"></label>\r\n            <label class=\"num\"><span>ค่าน้ำ (บาท/ลบ.ม.)</span><input type=\"number\" id=\"waterRate\" value=\"18\" min=\"0\" step=\"1\"></label>\r\n            <label class=\"num\"><span>น้ำที่ใช้ (ลิตร/หน่วย)</span><input type=\"number\" id=\"waterL\" value=\"1.5\" min=\"0\" step=\"0.1\"></label>\r\n            <label class=\"num\"><span>ค่าเช่าที่ (บาท/เดือน)</span><input type=\"number\" id=\"rent\" value=\"1500\" min=\"0\" step=\"100\"></label>\r\n            <label class=\"num\"><span>ค่าดูแล/ไส้กรอง (บาท/เดือน)</span><input type=\"number\" id=\"maint\" value=\"400\" min=\"0\" step=\"50\"></label>\r\n          </div>\r\n        </div>\r\n      </details>\r\n\r\n      <!-- 4. payment -->\r\n      <details class=\"acc\" open>\r\n        <summary>🏦 การชำระเงิน &amp; ดอกเบี้ย <span class=\"caret\">▾</span></summary>\r\n        <div class=\"acc-body\">\r\n          <div class=\"seg wide\" id=\"modeSeg\" style=\"margin-bottom:12px\">\r\n            <button data-mode=\"cash\" class=\"on\" type=\"button\">ซื้อเงินสด</button>\r\n            <button data-mode=\"loan\" type=\"button\">ผ่อนชำระ / ไฟแนนซ์</button>\r\n          </div>\r\n          <p id=\"cashHint\" style=\"font-size:10px;color:var(--ink-3);margin:0;font-weight:300\">\r\n            โหมดซื้อเงินสด ไม่มีค่างวดและดอกเบี้ย — เลือก “ผ่อนชำระ” เพื่อคำนวณค่างวดจากตารางดอกเบี้ย TSRL\r\n          </p>\r\n\r\n          <div id=\"loanInputs\">\r\n            <div class=\"field\">\r\n              <div class=\"field-top\"><label for=\"downPct\">เงินดาวน์</label><output id=\"downOut\">20%</output></div>\r\n              <input type=\"range\" id=\"downPct\" min=\"0\" max=\"50\" step=\"5\" value=\"20\">\r\n            </div>\r\n            <div class=\"grid2\">\r\n              <label class=\"num\"><span>จำนวนงวด (เดือน)</span>\r\n                <select class=\"sel\" id=\"term\">\r\n                  <option value=\"6\">6</option>\r\n                  <option value=\"12\">12</option>\r\n                  <option value=\"18\">18</option>\r\n                  <option value=\"21\">21</option>\r\n                  <option value=\"24\" selected>24</option>\r\n                  <option value=\"36\">36</option>\r\n                </select>\r\n              </label>\r\n              <label class=\"num\"><span>ดอกเบี้ยคงที่ (%/เดือน)</span>\r\n                <input type=\"number\" id=\"flatRate\" value=\"2.40\" min=\"0\" max=\"5\" step=\"0.01\">\r\n              </label>\r\n            </div>\r\n            <p style=\"font-size:9.5px;color:var(--ink-3);margin:7px 0 12px;font-weight:300\" id=\"rateHint\">อัตราอ้างอิงจากตาราง TSRL — แตะช่องในตารางเพื่อเลือกแผน</p>\r\n            <div class=\"matrix\" id=\"rateMatrix\"></div>\r\n          </div>\r\n        </div>\r\n      </details>\r\n\r\n      <div style=\"padding:12px 16px;border-top:1px solid var(--line-2);display:flex;gap:8px\">\r\n        <button class=\"btn solid\" id=\"btnReset\" type=\"button\" style=\"flex:1\">↺ รีเซ็ตค่าตั้งต้น</button>\r\n      </div>\r\n    </div>\r\n  </aside>\r\n\r\n  <!-- ============ RESULTS ============ -->\r\n  <main class=\"stack\">\r\n\r\n    <section class=\"kpis\">\r\n      <div class=\"kpi hero\" id=\"kpiRoiCard\">\r\n        <div class=\"k-label\">ROI ต่อปี</div>\r\n        <div class=\"k-val\" id=\"kpiRoi\">—</div>\r\n        <div class=\"k-sub\" id=\"kpiRoiSub\">ผลตอบแทนจากเงินลงทุนตัวเอง</div>\r\n        <div class=\"ring\" id=\"roiRing\" aria-hidden=\"true\"></div>\r\n      </div>\r\n      <div class=\"kpi\" id=\"kpiPaybackCard\">\r\n        <div class=\"k-label\">คืนทุน (Payback)</div>\r\n        <div class=\"k-val\" id=\"kpiPayback\">—</div>\r\n        <div class=\"k-sub\" id=\"kpiPaybackSub\">กระแสเงินสดสะสม</div>\r\n      </div>\r\n      <div class=\"kpi\" id=\"kpiProfitCard\">\r\n        <div class=\"k-label\">กำไรสุทธิ/เดือน</div>\r\n        <div class=\"k-val\" id=\"kpiProfit\">—</div>\r\n        <div class=\"k-sub\" id=\"kpiProfitSub\">หลังหักต้นทุนและค่างวด</div>\r\n      </div>\r\n      <div class=\"kpi\" id=\"kpiBeCard\">\r\n        <div class=\"k-label\">จุดคุ้มทุน</div>\r\n        <div class=\"k-val\" id=\"kpiBe\">—</div>\r\n        <div class=\"k-sub\" id=\"kpiBeSub\">ยอดขายขั้นต่ำต่อวัน</div>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- plain-language verdict for sales -->\r\n    <section class=\"verdict\" id=\"verdictCard\">\r\n      <div>\r\n        <span class=\"v-tag\">สรุปสั้นสำหรับลูกค้า</span>\r\n        <p id=\"verdictText\">—</p>\r\n      </div>\r\n      <div class=\"v-chips\">\r\n        <div><span>เงินลงทุนรวม</span><b id=\"vInvest\">—</b></div>\r\n        <div><span>กำไร/เดือน</span><b id=\"vProfit\">—</b></div>\r\n        <div><span>คืนทุน</span><b id=\"vPayback\">—</b></div>\r\n      </div>\r\n    </section>\r\n\r\n    <div class=\"seg\" id=\"viewSeg\">\r\n      <button data-view=\"overview\" class=\"on\" type=\"button\">ภาพรวม</button>\r\n      <button data-view=\"cashflow\" type=\"button\">กระแสเงินสด</button>\r\n      <button data-view=\"loan\" type=\"button\">ค่างวด &amp; ดอกเบี้ย</button>\r\n      <button data-view=\"notes\" type=\"button\">สูตร &amp; ที่มา</button>\r\n    </div>\r\n\r\n    <!-- ---------- overview ---------- -->\r\n    <section class=\"view\" id=\"view-overview\">\r\n      <div class=\"stack\">\r\n        <div class=\"card\">\r\n          <div class=\"card-head\"><h2>🎯 จุดคุ้มทุน &amp; กำไรต่อหน่วย</h2><span class=\"hint\" id=\"beHint\">ต่อเดือน 30 วัน</span></div>\r\n          <div class=\"card-body\">\r\n            <div class=\"be-grid\">\r\n              <div class=\"be\"><span>ขายขั้นต่ำเพื่อไม่ขาดทุน</span><b id=\"beQty\">—</b><small id=\"beQtyUnit\">หน่วย/วัน</small></div>\r\n              <div class=\"be\"><span>รายได้ขั้นต่ำ</span><b id=\"beRevenue\">—</b><small>บาท/เดือน</small></div>\r\n              <div class=\"be\"><span>กำไรส่วนเพิ่มต่อหน่วย</span><b id=\"beContrib\">—</b><small>บาท/หน่วย</small></div>\r\n            </div>\r\n            <div class=\"note\" id=\"beNote\" style=\"margin-top:12px\"></div>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"card\">\r\n          <div class=\"card-head\"><h2>💰 โครงสร้างรายรับ–รายจ่าย</h2><span class=\"hint\" id=\"revHint\">รายรับ 0 บาท/เดือน</span></div>\r\n          <div class=\"card-body\">\r\n            <div class=\"cbar\" id=\"costBar\"></div>\r\n            <div class=\"legend\" id=\"costLegend\"></div>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"card\">\r\n          <div class=\"card-head\"><h2>⚖️ เทียบ 2 ทางเลือก: เงินสด vs ผ่อนชำระ</h2><span class=\"hint\">ใช้ยอดขายชุดเดียวกัน</span></div>\r\n          <div class=\"card-body\">\r\n            <div class=\"cmp\" id=\"cmpBox\"></div>\r\n            <p style=\"font-size:10px;color:var(--ink-3);margin:10px 0 0;font-weight:300\" id=\"cmpNote\"></p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"card\">\r\n          <div class=\"card-head\"><h2>🔀 ทดสอบความเสี่ยง (Sensitivity)</h2><span class=\"hint\">ยอดขายเปลี่ยน ±30%</span></div>\r\n          <div class=\"card-body\">\r\n            <div class=\"sens\" id=\"sensGrid\"></div>\r\n            <p style=\"font-size:10px;color:var(--ink-3);margin:10px 0 0;font-weight:300\">\r\n              ใช้ดูว่าถ้ายอดขายพลาดเป่า 30% ระยะเวลาคืนทุนจะยืดออกไปเท่าไร ก่อนเซ็นสัญญาเช่าพื้นที่\r\n            </p>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- ---------- cashflow ---------- -->\r\n    <section class=\"view\" id=\"view-cashflow\" hidden>\r\n      <div class=\"stack\">\r\n        <div class=\"card\">\r\n          <div class=\"card-head\"><h2>🧮 ตัวชี้วัดขั้นสูง</h2><span class=\"hint\">สำหรับวิเคราะห์เชิงลึก (ไม่จำเป็นต่อการนำเสนอ)</span></div>\r\n          <div class=\"card-body\">\r\n            <div class=\"be-grid\">\r\n              <div class=\"be\"><span>NPV (มูลค่าปัจจุบันสุทธิ)</span><b id=\"advNpv\">—</b><small>คิดลดที่อัตราคิดลดที่ตั้งไว้</small></div>\r\n              <div class=\"be\"><span>IRR (ผลตอบแทนที่แท้จริง)</span><b id=\"advIrr\">—</b><small>ต่อปี</small></div>\r\n              <div class=\"be\"><span>PI (Profitability Index)</span><b id=\"advPi\">—</b><small>มากกว่า 1 คือคุ้มลงทุน</small></div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <div class=\"card\">\r\n          <div class=\"card-head\"><h2>📊 กระแสเงินสดสะสม</h2><span class=\"hint\" id=\"chartHint\">—</span></div>\r\n          <div class=\"card-body\">\r\n            <div class=\"chart-wrap\"><canvas id=\"cashChart\"></canvas><div class=\"chart-tip\" id=\"chartTip\"></div></div>\r\n          </div>\r\n        </div>\r\n        <div class=\"card\">\r\n          <div class=\"card-head\"><h2>🗓️ ตารางกระแสเงินสดรายปี</h2><span class=\"hint\">มูลค่าปัจจุบันคิดส่วนลดรายเดือน</span></div>\r\n          <div class=\"card-body\">\r\n            <div class=\"tbl-wrap\">\r\n              <table>\r\n                <thead>\r\n                  <tr>\r\n                    <th>ปี</th><th>รายรับ</th><th>ต้นทุนดำเนินงาน</th><th>ค่างวด</th>\r\n                    <th>กระแสเงินสดสุทธิ</th><th>สะสม</th><th>มูลค่าปัจจุบัน</th>\r\n                  </tr>\r\n                </thead>\r\n                <tbody id=\"yearBody\"></tbody>\r\n              </table>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- ---------- loan ---------- -->\r\n    <section class=\"view\" id=\"view-loan\" hidden>\r\n      <div class=\"stack\">\r\n        <div class=\"card\">\r\n          <div class=\"card-head\"><h2>🏦 โครงสร้างการผ่อนชำระ</h2><span class=\"hint\" id=\"loanHint\">—</span></div>\r\n          <div class=\"card-body\" id=\"loanSummary\"></div>\r\n        </div>\r\n        <div class=\"card\">\r\n          <div class=\"card-head\"><h2>📋 ตารางผ่อนชำระ</h2><span class=\"hint\" id=\"amortHint\">—</span></div>\r\n          <div class=\"card-body\">\r\n            <div class=\"tbl-wrap\">\r\n              <table>\r\n                <thead>\r\n                  <tr><th>งวด</th><th>ค่างวด</th><th>เงินต้น</th><th>ดอกเบี้ย</th><th>คงเหลือ</th></tr>\r\n                </thead>\r\n                <tbody id=\"amortBody\"></tbody>\r\n              </table>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- ---------- notes ---------- -->\r\n    <section class=\"view notes\" id=\"view-notes\" hidden>\r\n      <div class=\"stack\">\r\n        <div class=\"card\">\r\n          <div class=\"card-head\"><h2>🧮 สูตรการคำนวณที่ใช้</h2><span class=\"hint\">มาตรฐานการวิเคราะห์การลงทุน</span></div>\r\n          <div class=\"card-body\">\r\n            <h4>1) รายรับ–ต้นทุนต่อเดือน (30 วัน)</h4>\r\n            <div class=\"formula\">\r\nรายรับ = ปริมาณขาย/วัน × ราคา/หน่วย × 30\r\nต้นทุนผันแปร = วัตถุดิบ + ค่าธรรมเนียม QR + ค่าไฟ + ค่าน้ำ\r\nค่าไฟ = กำลังไฟ(kW) × ชั่วโมงทำงาน × 30 × เรตค่าไฟ\r\nค่าน้ำ = ปริมาณขาย/วัน × ลิตรต่อหน่วย ÷ 1000 × เรตค่าน้ำ × 30\r\nค่าธรรมเนียม QR = รายรับ × สัดส่วนจ่าย QR × อัตราค่าธรรมเนียม\r\n            </div>\r\n\r\n            <h4>2) กระแสเงินสด &amp; ผลตอบแทน</h4>\r\n            <div class=\"formula\">\r\nNCF = รายรับ − ต้นทุนดำเนินงาน − ค่างวด (ถ้ามี)\r\nROI ต่อปี = NCF × 12 ÷ เงินลงทุนตัวเอง × 100\r\nPayback = เดือนแรกที่กระแสเงินสดสะสม ≥ เงินลงทุนตัวเอง\r\nNPV = −เงินลงทุน + Σ [ CFₜ ÷ (1+r)^(t/12) ] + มูลค่าซาก\r\nIRR = อัตรา r ที่ทำให้ NPV = 0  (แสดงเป็นอัตราทบต้นต่อปี)\r\n            </div>\r\n\r\n            <h4>3) ค่างวด &amp; ดอกเบี้ย</h4>\r\n            <div class=\"formula\">\r\nแบบคงที่ (Flat rate — ตาราง TSRL)\r\n  ดอกเบี้ยรวม = ยอดจัดไฟแนนซ์ × อัตรา/เดือน × จำนวนงวด\r\n  ค่างวด = (ยอดจัด + ดอกเบี้ยรวม) ÷ จำนวนงวด\r\n\r\nแบบลดต้นลดดอก ( annuity )\r\n  i = APR ÷ 12,  ค่างวด = P × i ÷ (1 − (1+i)^−n)\r\n\r\nAPR แท้จริงของแผนคงที่ = อัตรา IRR ต่อเดือน × 12 (เทียบกับสินเชื่อลดต้นลดดอก)\r\n            </div>\r\n\r\n            <h4>4) จุดคุ้มทุน</h4>\r\n            <div class=\"formula\">\r\nกำไรส่วนเพิ่ม/หน่วย = ราคา − วัตถุดิบ − ค่าน้ำ/หน่วย − ค่า QR ต่อหน่วย\r\nจุดคุ้มทุน (หน่วย/วัน) = (ค่าเช่า + ค่าดูแล + ค่าไฟ + ค่างวด) ÷ (กำไรส่วนเพิ่ม × 30)\r\n            </div>\r\n\r\n            <p style=\"margin-top:12px\">* ตัวเลขทั้งหมดเป็นการประมาณการเพื่อการตัดสินใจเบื้องต้น ไม่ใช่การรับประกันผลตอบแทน</p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"card\">\r\n          <div class=\"card-head\"><h2>🧺 สมมติฐานเครื่องซักผ้า (อ้างอิงเอกสาร)</h2><span class=\"hint\">PM9003/2569 · BOQ ติดตั้ง · จุดคืนทุน 2569</span></div>\r\n          <div class=\"card-body\">\r\n            <h4>1) ราคาขายเงินสด — LG เครื่องซักผ้าหยอดเหรียญ (PM9003/2569 ข้อ 9)</h4>\r\n            <div class=\"tbl-wrap\" style=\"max-height:300px;margin-bottom:14px\">\r\n              <table>\r\n                <thead><tr><th>รหัส</th><th>รายการ</th><th>ราคาเงินสด</th></tr></thead>\r\n                <tbody>\r\n                  <tr><td class=\"em\">10501614</td><td>LG ซักผ้าฝาบน 17 กก. T2517VBTB + กล่องหยอดเหรียญ</td><td>28,900</td></tr>\r\n                  <tr><td class=\"em\">10501822</td><td>LG ซักผ้าฝาบน 17 กก. T2517VBTB + ชุดหยอดเหรียญ + QR</td><td>35,900</td></tr>\r\n                  <tr><td class=\"em\">10501777</td><td>LG ซักผ้าหน้า 13 กก. + ชุดหยอดเหรียญ (ซักเดี่ยว)</td><td>76,900</td></tr>\r\n                  <tr><td class=\"em\">10501818</td><td>LG ซักผ้าหน้า Single 13 กก. + ชุด + QR</td><td>82,900</td></tr>\r\n                  <tr><td class=\"em\">10501779</td><td>LG ซักผ้าหน้า 17 กก. + ชุดหยอดเหรียญ (ซักเดี่ยว)</td><td>101,900</td></tr>\r\n                  <tr><td class=\"em\">10501819</td><td>LG ซักผ้าหน้า Single 17 กก. + ชุด + QR</td><td>107,900</td></tr>\r\n                  <tr><td class=\"em\">10501778</td><td>LG อบผ้า 13 กก. + ชุดหยอดเหรียญ (อบเดี่ยว)</td><td>62,900</td></tr>\r\n                  <tr><td class=\"em\">10501820</td><td>LG อบผ้า Single 13 กก. + ชุด + QR</td><td>68,900</td></tr>\r\n                  <tr><td class=\"em\">10501780</td><td>LG อบผ้า 17 กก. + ชุดหยอดเหรียญ (อบเดี่ยว)</td><td>79,900</td></tr>\r\n                  <tr><td class=\"em\">10501821</td><td>LG อบผ้า Single 17 กก. + ชุด + QR</td><td>85,900</td></tr>\r\n                  <tr><td class=\"em\">10501609</td><td>LG Stack ซัก 13 + อบ 10 กก. + ชุดหยอดเหรียญ</td><td>145,900</td></tr>\r\n                  <tr><td class=\"em\">10501816</td><td>LG Stack 13 + 10 + ชุด + QR</td><td>158,900</td></tr>\r\n                  <tr><td class=\"em\">10501611</td><td>LG Stack ซัก 17 + อบ 13 กก. + ชุดหยอดเหรียญ</td><td>185,900</td></tr>\r\n                  <tr><td class=\"em\">10501817</td><td>LG Stack 17 + 13 + ชุด + QR</td><td>198,900</td></tr>\r\n                </tbody>\r\n              </table>\r\n            </div>\r\n\r\n            <h4>2) ค่าเตรียมพื้นที่ติดตั้ง (BOQ เครื่องซักผ้า)</h4>\r\n            <div class=\"formula\">\r\n1 เครื่อง = 6,010   ·   2 เครื่อง = 11,245   ·   3 เครื่อง = 16,780\r\n4 เครื่อง = 22,765  ·   5 เครื่อง = 29,425\r\n(ท่อน้ำดี 30 บ./ม. · ท่อน้ำทิ้ง 40 บ./ม. · ก๊อกน้ำ 500 บ./ชุด · ท่อลมร้อน 1,500 บ./ชุด\r\n สายไฟ 100/50 บ./ม. · เบรกเกอร์ 130 บ./ชุด · ปลั๊ก 500 บ./ชุด · ค่าแรง 1,200 บ./เครื่อง)\r\nงานเสริม: ปรับพื้น 1,000/ตรม. · หลังคา 1,500/ตรม. · ผนัง 1,500/ตรม.\r\nตู้ไฟ 1 เฟส 12,000 · 3 เฟส 30,000 · มาตรวัดน้ำ 700\r\n            </div>\r\n\r\n            <h4>3) สมมติฐานการใช้งาน (จุดคืนทุน_BU_Vending_2569)</h4>\r\n            <div class=\"formula\">\r\nซักผ้าฝาบน 28,900 บ. · 5 รอบ/วัน · 30 บ./รอบ · ค่าใช้จ่าย 6% ของรายได้\r\n  → กำไร 4,230 บ./เดือน · คืนทุน 6.8 เดือน · ROI 176%/ปี\r\nซัก-อบ ฝาหน้า 185,900 บ. · 10 รอบ/วัน · 80 บ./รอบ · ค่าใช้จ่าย 15% ของรายได้\r\n  → กำไร 20,400 บ./เดือน/เครื่อง · คืนทุน 9.1 เดือน · ROI 132%/ปี\r\n            </div>\r\n            <p style=\"margin-top:10px\">แบบจำลองนี้คิดค่าไฟ/ค่าน้ำแยกจริง (ไม่ใช้ % ของรายได้) จึงได้คืนทุนของ Stack 17+13 ประมาณ 9 เดือน ใกล้เคียงสมมติฐาน BU</p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"card\">\r\n          <div class=\"card-head\"><h2>📁 ที่มาของข้อมูล</h2><span class=\"hint\">รวบรวมจากไฟล์ในเครื่อง</span></div>\r\n          <div class=\"card-body\">\r\n            <div class=\"src\"><b>ROI / คืนทุน</b><span>safe_vending_roi_calculator.html — โครงสร้างรายรับ–ต้นทุนตู้หยอดเหรียญ 3 ชนิด (น้ำด่าง / น้ำแข็ง / กาแฟ), เงินดาวน์–ดอกเบี้ย–ค่างวด, ROI และ Payback</span></div>\r\n            <div class=\"src\"><b>ตารางดอกเบี้ย</b><span>คำนวณราคาผ่อนสินค้า TSRL.xlsx (ชีต Interest) — อัตราดอกเบี้ยคงที่ต่อเดือน แยกตามเงินดาวน์ 0–50% และงวด 6/12/18/21/24/36 เดือน</span></div>\r\n            <div class=\"src\"><b>จุดคืนทุน</b><span>จุดคืนทุน_BU_Vending_2569.xlsx — แนวคิด Break-even, สัดส่วนค่าใช้จ่ายต่อรายได้, ROI ต่อปี (ตู้กดน้ำ RO / ตู้กาแฟ / เครื่องซักผ้า / ซัก-อบ)</span></div>\r\n            <div class=\"src\"><b>ราคาเครื่องซักผ้า</b><span>PM9003-2569 ประกาศเรื่องราคาจำหน่ายสินค้าของบริษัทฯ (ข้อ 9 เครื่องซักผ้าหยอดเหรียญ LG 14 รุ่น) และไฟล์ราคาใน DRS CRD TELE_Rev.plan เครื่องซักผ้า หยอดเหรียญ (ALL).xlsx</span></div>\r\n            <div class=\"src\"><b>ราคาตู้กดน้ำ</b><span>ตู้น้ำลิตร หยอดเหรียญ V3 + ชุดติดตั้ง 45,900 บาท (Project Vending SML REV01.xlsx) · A01 Water Mate 14,900 บาท</span></div>\r\n            <div class=\"src\"><b>ราคาเครื่องทำน้ำแข็ง</b><span>PM9003-2569 ตารางราคาเครื่องทำน้ำแข็งพร้อมเครื่องกรองน้ำ RO (FC 180-1 / FH-180 / FC-180 / FC-140 / FH-140 / FC-90 / FH-90 / FH-60)</span></div>\r\n            <div class=\"src\"><b>ค่าติดตั้ง</b><span>คำนวนงานก่อสร้าง (เครื่องซักผ้า).xlsx (ชีต Sim Cost) — BOQ เตรียมพื้นที่ 1–5 เครื่อง</span></div>\r\n            <div class=\"src\"><b>หลักการมาตรฐาน</b><span>NPV / IRR / Payback / Break-even ตามหลักการวิเคราะห์โครงการลงทุน (capital budgeting) และการเทียบค่างวดแบบ Flat rate กับ ลดต้นลดดอก (APR)</span></div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </section>\r\n\r\n    <p style=\"text-align:center;font-size:10px;color:var(--ink-3);padding:2px 0 8px\">\r\n      ROI Studio · ผลคำนวณเป็นการประมาณการ ใช้ประกอบการตัดสินใจ ไม่ใช่การรับประกันผลตอบแทน\r\n    </p>\r\n  </main>\r\n</div>\r\n\r\n<div class=\"toast\" id=\"toast\">คัดลอกสรุปแล้ว</div>\r\n\r\n<script>\r\n/* ============================================================\r\n   ROI Studio — single file app\r\n   ============================================================ */\r\nconst $  = (s, r = document) => r.querySelector(s);\r\nconst $$ = (s, r = document) => Array.from(r.querySelectorAll(s));\r\n\r\n/* ---------- asset presets ---------- */\r\nconst PRESETS = {\r\n  alkaline: { label:'ตู้กดน้ำด่าง', emoji:'💧', unit:'ลิตร', unitShort:'ลิตร/วัน',\r\n    price:45900, baseQty:100, qtyMax:400, unitPrice:5, unitMin:1, unitMax:10,\r\n    rawCost:0, qrShare:60, qrFee:1, elecKW:0.15, elecHours:12, elecRate:4,\r\n    waterL:1.5, waterRate:18, rent:1500, maint:400, flatRate:2.40 },\r\n  ice: { label:'ตู้ผลิตน้ำแข็ง', emoji:'❄️', unit:'กก.', unitShort:'กก./วัน',\r\n    price:142500, baseQty:65, qtyMax:150, unitPrice:5, unitMin:2, unitMax:15,\r\n    rawCost:0, qrShare:70, qrFee:1, elecKW:1.33, elecHours:12, elecRate:4,\r\n    waterL:1.3, waterRate:18, rent:2000, maint:500, flatRate:2.90 },\r\n  coffee: { label:'ตู้กาแฟ 10 บาท', emoji:'☕', unit:'แก้ว', unitShort:'แก้ว/วัน',\r\n    price:49000, baseQty:60, qtyMax:200, unitPrice:10, unitMin:10, unitMax:20,\r\n    rawCost:4.5, qrShare:60, qrFee:1, elecKW:1.5, elecHours:12, elecRate:4,\r\n    waterL:0.2, waterRate:18, rent:1500, maint:300, flatRate:2.90 },\r\n  laundry: { label:'เครื่องซักผ้า / อบผ้า (LG)', emoji:'🧺', unit:'รอบ', unitShort:'รอบ/วัน',\r\n    price:28900, baseQty:5, qtyMax:24, unitPrice:30, unitMin:10, unitMax:100,\r\n    rawCost:0, qrShare:30, qrFee:1, elecKW:0.5, elecHours:3, elecRate:4,\r\n    waterL:120, waterRate:18, rent:0, maint:200, flatRate:2.40 }\r\n};\r\n\r\n/* ---------- แคตตาล็อกรุ่นสินค้า (ราคาขายเงินสด) ---------- */\r\nconst MODELS = {\r\n  alkaline: [\r\n    { code:'10501613', name:'ตู้น้ำลิตร หยอดเหรียญ V3 + ชุดติดตั้ง (ไม่รวมมิเตอร์น้ำ-ไฟ)', price:45900 },\r\n    { code:'10100296', name:'A01 Water Mate ตู้กดน้ำ', price:14900 }\r\n  ],\r\n  ice: [\r\n    { code:'10500847', name:'น้ำแข็งหลอดหนาพิเศษ FC 180-1 (180 กก./วัน)', price:142500 },\r\n    { code:'10500829', name:'น้ำแข็งหลอดบาง FH-180 (180 กก./วัน)', price:136500 },\r\n    { code:'10500830', name:'น้ำแข็งหลอดหนา FC-180 (180 กก./วัน)', price:123500 },\r\n    { code:'10500828', name:'น้ำแข็งหลอดหนา FC-140 (140 กก./วัน)', price:94500 },\r\n    { code:'10500827', name:'น้ำแข็งหลอดบาง FH-140 (140 กก./วัน)', price:94500 },\r\n    { code:'10500826', name:'น้ำแข็งหลอดหนา FC-90 (90 กก./วัน)', price:64500 },\r\n    { code:'10500825', name:'น้ำแข็งหลอดบาง FH-90 (90 กก./วัน)', price:64500 },\r\n    { code:'10500821', name:'น้ำแข็งหลอดบาง FH-60 (60 กก./วัน)', price:51500 }\r\n  ],\r\n  laundry: [\r\n    { code:'10501614', name:'LG ซักผ้าฝาบน 17 กก. T2517VBTB + กล่องหยอดเหรียญ', price:28900,  type:'top' },\r\n    { code:'10501822', name:'LG ซักผ้าฝาบน 17 กก. T2517VBTB + ชุดหยอดเหรียญ + QR', price:35900, type:'top' },\r\n    { code:'10501777', name:'LG ซักผ้าหน้า 13 กก. + ชุดหยอดเหรียญ', price:76900,  type:'front' },\r\n    { code:'10501818', name:'LG ซักผ้าหน้า Single 13 กก. + ชุด + QR', price:82900, type:'front' },\r\n    { code:'10501779', name:'LG ซักผ้าหน้า 17 กก. + ชุดหยอดเหรียญ', price:101900, type:'front' },\r\n    { code:'10501819', name:'LG ซักผ้าหน้า Single 17 กก. + ชุด + QR', price:107900, type:'front' },\r\n    { code:'10501778', name:'LG อบผ้า 13 กก. + ชุดหยอดเหรียญ', price:62900,  type:'dryer' },\r\n    { code:'10501820', name:'LG อบผ้า Single 13 กก. + ชุด + QR', price:68900, type:'dryer' },\r\n    { code:'10501780', name:'LG อบผ้า 17 กก. + ชุดหยอดเหรียญ', price:79900,  type:'dryer' },\r\n    { code:'10501821', name:'LG อบผ้า Single 17 กก. + ชุด + QR', price:85900, type:'dryer' },\r\n    { code:'10501609', name:'LG Stack 13 ซัก + 10 อบ + ชุดหยอดเหรียญ', price:145900, type:'stack' },\r\n    { code:'10501816', name:'LG Stack 13 + 10 + ชุด + QR', price:158900, type:'stack' },\r\n    { code:'10501611', name:'LG Stack 17 ซัก + 13 อบ + ชุดหยอดเหรียญ', price:185900, type:'stack' },\r\n    { code:'10501817', name:'LG Stack 17 + 13 + ชุด + QR', price:198900, type:'stack' }\r\n  ]\r\n};\r\n\r\nconst DEFAULT_MODEL = { alkaline:'10501613', ice:'10500847', laundry:'10501614' };\r\n\r\nconst MODEL_LABEL = {\r\n  alkaline: 'รุ่นตู้กดน้ำ — ราคาที่ส่งลูกค้า',\r\n  ice: 'รุ่นเครื่องทำน้ำแข็ง — PM9003/2569',\r\n  laundry: 'รุ่นสินค้า — PM9003/2569 (ราคาเงินสด)'\r\n};\r\n\r\nconst LAUNDRY_TYPE = {\r\n  top:   { unitPrice:30, waterL:120, elecKW:0.5, elecHours:3, baseQty:5,  qtyMax:24 },\r\n  front: { unitPrice:30, waterL:130, elecKW:0.6, elecHours:3, baseQty:5,  qtyMax:24 },\r\n  dryer: { unitPrice:40, waterL:0,   elecKW:3.0, elecHours:3, baseQty:3,  qtyMax:20 },\r\n  stack: { unitPrice:80, waterL:120, elecKW:3.3, elecHours:6, baseQty:10, qtyMax:24 }\r\n};\r\n\r\n/* BOQ ค่าเตรียมพื้นที่ติดตั้ง (เครื่องซักผ้า) ตามจำนวนเครื่อง */\r\nconst BOQ_INSTALL = { 1:6010, 2:11245, 3:16780, 4:22765, 5:29425 };\r\n\r\n/* ---------- TSRL rate table (% per month, flat) ---------- */\r\nconst RATE = {\r\n  downs: [0, 10, 15, 20, 30, 40, 50],\r\n  terms: [6, 12, 18, 21, 24, 36],\r\n  rows: [\r\n    [2.00, 2.25, 2.50, 2.75, 3.00, 3.25],  // down 0%\r\n    [2.00, 2.25, 2.50, 2.75, 3.00, 3.25],  // down 10%\r\n    [1.95, 2.20, 2.45, 2.70, 2.95, 3.20],  // down 15%\r\n    [1.90, 2.15, 2.40, 2.65, 2.90, 3.15],  // down 20%\r\n    [1.80, 2.05, 2.30, 2.55, 2.80, 3.05],  // down 30%\r\n    [1.60, 1.70, 1.80, 1.90, 2.00, 2.10],  // down 40%\r\n    [1.50, 1.60, 1.70, 1.80, 1.90, 2.00]   // down 50%\r\n  ]\r\n};\r\n\r\nfunction lookupRate(downPct, term) {\r\n  const col = RATE.terms.indexOf(Number(term));\r\n  if (col < 0) return 2.4;\r\n  const x = Math.min(50, Math.max(0, downPct));\r\n  let i = 0;\r\n  while (i < RATE.downs.length - 1 && x > RATE.downs[i + 1]) i++;\r\n  const j = Math.min(i + 1, RATE.downs.length - 1);\r\n  const x0 = RATE.downs[i], x1 = RATE.downs[j];\r\n  const r0 = RATE.rows[i][col], r1 = RATE.rows[j][col];\r\n  return x1 === x0 ? r0 : r0 + (r1 - r0) * (x - x0) / (x1 - x0);\r\n}\r\n\r\n/* ---------- state ---------- */\r\nconst state = { preset:'alkaline', scenario:'base', mode:'cash', view:'overview' };\r\n\r\n/* ---------- formatting ---------- */\r\nconst nf0 = new Intl.NumberFormat('th-TH', { maximumFractionDigits: 0 });\r\nconst nf2 = new Intl.NumberFormat('th-TH', { minimumFractionDigits: 1, maximumFractionDigits: 1 });\r\nconst nf1 = new Intl.NumberFormat('th-TH', { minimumFractionDigits: 1, maximumFractionDigits: 1 });\r\n\r\nfunction baht(n) {\r\n  if (!isFinite(n)) return '—';\r\n  const s = nf0.format(Math.abs(Math.round(n)));\r\n  return (n < 0 ? '−' : '') + '฿' + s;\r\n}\r\nfunction bahtSigned(n) {\r\n  if (!isFinite(n)) return '—';\r\n  return (n > 0 ? '+' : '') + baht(n);\r\n}\r\nfunction pct(v, d = 1) {\r\n  if (!isFinite(v)) return '—';\r\n  return (v * 100).toFixed(d) + '%';\r\n}\r\nfunction compact(n) {\r\n  const a = Math.abs(n);\r\n  if (a >= 1e6) return (n / 1e6).toFixed(a >= 1e7 ? 0 : 1) + 'M';\r\n  if (a >= 1e3) return Math.round(n / 1e3) + 'K';\r\n  return String(Math.round(n));\r\n}\r\nfunction pctCap(v) {\r\n  if (!isFinite(v)) return '—';\r\n  if (v > 5) return '>500%';\r\n  return pct(v);\r\n}\r\nfunction monthText(m) {\r\n  if (m == null || !isFinite(m)) return 'ไม่คืนทุน';\r\n  if (m <= 0) return 'ทันที';\r\n  let y = Math.floor(m / 12);\r\n  let mo = Math.round(m - y * 12);\r\n  if (mo === 12) { y += 1; mo = 0; }\r\n  if (y > 0 && mo > 0) return `${y} ปี ${mo} เดือน`;\r\n  if (y > 0) return `${y} ปี`;\r\n  return `${Math.max(1, Math.round(m))} เดือน`;\r\n}\r\n\r\nconst num = id => { const el = document.getElementById(id); const v = parseFloat(el.value); return isFinite(v) ? v : 0; };\r\n\r\n/* ---------- micro-interactions ---------- */\r\nconst prevKpi = {};\r\nfunction flashKpi(cardId) {\r\n  const card = document.getElementById(cardId);\r\n  if (!card) return;\r\n  card.classList.remove('flash');\r\n  void card.offsetWidth;\r\n  card.classList.add('flash');\r\n}\r\nfunction setKpi(id, cardId, text) {\r\n  const el = document.getElementById(id);\r\n  if (!el || el.textContent === text) return;\r\n  el.textContent = text;\r\n  if (prevKpi[id] !== undefined) flashKpi(cardId);\r\n  prevKpi[id] = text;\r\n}\r\nlet chartGeom = null;\r\n\r\n/* ---------- core engine ---------- */\r\nfunction irr(cashflows) {\r\n  const npvAt = r => cashflows.reduce((s, cf, i) => s + cf / Math.pow(1 + r, i), 0);\r\n  let lo = -0.9999, hi = 1, flo = npvAt(lo), fhi = npvAt(hi), guard = 0;\r\n  while (flo * fhi > 0 && guard++ < 80) { hi *= 1.7; fhi = npvAt(hi); }\r\n  if (flo * fhi > 0) return NaN;\r\n  for (let k = 0; k < 240; k++) {\r\n    const mid = (lo + hi) / 2, fm = npvAt(mid);\r\n    if (Math.abs(fm) < 1e-7) return mid;\r\n    if (flo * fm <= 0) { hi = mid; fhi = fm; } else { lo = mid; flo = fm; }\r\n  }\r\n  return (lo + hi) / 2;\r\n}\r\n\r\nfunction core(p) {\r\n  const revenue = p.qty * p.unitPrice * 30;\r\n  const raw     = p.qty * p.rawCost * 30;\r\n  const qr      = revenue * (p.qrShare / 100) * (p.qrFee / 100);\r\n  const elec    = p.elecKW * p.elecHours * 30 * p.elecRate;\r\n  const water   = (p.qty * p.waterL / 1000) * p.waterRate * 30;\r\n  const fixed   = p.rent + p.maint;\r\n  const opex    = raw + qr + elec + water + fixed;\r\n\r\n  let principal = 0, down = p.price, interest = 0, pmt = 0;\r\n  if (p.mode === 'loan') {\r\n    down = p.price * (p.downPct / 100);\r\n    principal = Math.max(0, p.price - down);\r\n    interest = principal * (p.flatRate / 100) * p.term;\r\n    pmt = p.term > 0 ? (principal + interest) / p.term : 0;\r\n  }\r\n  const equity = p.mode === 'loan' ? down : p.price;\r\n\r\n  const opProfit = revenue - opex;\r\n  const months = Math.round(p.years * 12);\r\n  const monthly = [];\r\n  let cum = -equity;\r\n  const cumSeries = [{ m: 0, cum }];\r\n  for (let m = 1; m <= months; m++) {\r\n    const payM = (p.mode === 'loan' && m <= p.term) ? pmt : 0;\r\n    let cf = opProfit - payM;\r\n    if (m === months) cf += p.salvage;\r\n    cum += cf;\r\n    monthly.push({ m, rev: revenue, opex, pay: payM, cf, cum });\r\n    cumSeries.push({ m, cum });\r\n  }\r\n\r\n  // payback (months, fractional)\r\n  let payback = null;\r\n  if (equity <= 0) payback = 0;\r\n  else {\r\n    for (let i = 1; i < cumSeries.length; i++) {\r\n      if (cumSeries[i].cum >= 0) {\r\n        const prev = cumSeries[i - 1].cum, cur = cumSeries[i].cum;\r\n        const frac = cur !== prev ? (-prev) / (cur - prev) : 0;\r\n        payback = (i - 1) + frac;\r\n        break;\r\n      }\r\n    }\r\n  }\r\n\r\n  const ncf = opProfit - (p.mode === 'loan' ? pmt : 0);\r\n  const roi = equity > 0 ? (ncf * 12) / equity : Infinity;\r\n\r\n  const r = p.discount / 100;\r\n  let npv = -equity;\r\n  monthly.forEach(row => { npv += row.cf / Math.pow(1 + r, row.m / 12); });\r\n\r\n  const flows = [-equity, ...monthly.map(x => x.cf)];\r\n  const iM = irr(flows);\r\n  const irrAnnual = isFinite(iM) ? Math.pow(1 + iM, 12) - 1 : NaN;\r\n\r\n  // break-even\r\n  const qrPerUnit = p.unitPrice * (p.qrShare / 100) * (p.qrFee / 100);\r\n  const contribution = p.unitPrice - p.rawCost - (p.waterL / 1000) * p.waterRate - qrPerUnit;\r\n  const fixedMonthly = fixed + elec + (p.mode === 'loan' ? pmt : 0);\r\n  const beQty = contribution > 0 ? fixedMonthly / (contribution * 30) : null;\r\n\r\n  return {\r\n    revenue, raw, qr, elec, water, fixed, opex, opProfit,\r\n    principal, down, interest, pmt, equity, ncf, roi, payback, npv, irrAnnual,\r\n    months, monthly, cumSeries, contribution, beQty,\r\n    beRevenue: beQty != null ? beQty * p.unitPrice * 30 : null,\r\n    margin: revenue > 0 ? opProfit / revenue : 0\r\n  };\r\n}\r\n\r\n/* ---------- read inputs ---------- */\r\nfunction readInputs() {\r\n  return {\r\n    preset: state.preset, mode: state.mode,\r\n    price: num('price') + num('install'), years: num('years'), discount: num('discount'), salvage: num('salvage'),\r\n    qty: num('qty'), unitPrice: num('unitPrice'),\r\n    rawCost: num('rawCost'), qrShare: num('qrShare'), qrFee: num('qrFee'),\r\n    elecKW: num('elecKW'), elecHours: num('elecHours'), elecRate: num('elecRate'),\r\n    waterL: num('waterL'), waterRate: num('waterRate'),\r\n    rent: num('rent'), maint: num('maint'),\r\n    downPct: num('downPct'), term: num('term'), flatRate: num('flatRate')\r\n  };\r\n}\r\n\r\n/* ---------- slider fill ---------- */\r\nfunction paintRange(el) {\r\n  const min = Number(el.min || 0), max = Number(el.max || 100);\r\n  const v = Number(el.value);\r\n  const f = max > min ? ((v - min) / (max - min)) * 100 : 0;\r\n  el.style.setProperty('--fill', f + '%');\r\n}\r\n\r\n/* ---------- render: labels ---------- */\r\nfunction renderLabels(p) {\r\n  const cfg = PRESETS[state.preset];\r\n  $('#qtyOut').textContent = `${nf0.format(p.qty)} ${cfg.unit}`;\r\n  $('#priceOut').textContent = nf2.format(p.unitPrice) + ' บาท';\r\n  $('#qrShareOut').textContent = p.qrShare + '%';\r\n  $('#downOut').textContent = p.downPct + '%';\r\n  $('#unitMinOut').textContent = cfg.unitMin + ' บาท';\r\n  $('#unitMaxOut').textContent = cfg.unitMax + ' บาท';\r\n  $('#qtyMaxOut').textContent = cfg.qtyMax;\r\n  $('#topMachine').textContent = cfg.label;\r\n  const inst = num('install');\r\n  $('#investHint').textContent = inst > 0\r\n    ? `รวมค่าติดตั้ง ${baht(inst)} → เงินลงทุนจริง ${baht(num('price') + inst)}`\r\n    : '';\r\n  $$('input[type=range]').forEach(paintRange);\r\n}\r\n\r\n/* ---------- model catalogue ---------- */\r\nfunction populateModels(presetKey, selected) {\r\n  const sel = $('#modelSel');\r\n  if (!sel) return;\r\n  const list = MODELS[presetKey] || [];\r\n  sel.innerHTML = '<option value=\"\">— กำหนดราคาเอง (แก้ช่องราคาได้) —</option>'\r\n    + list.map(m => `<option value=\"${m.code}\">${m.code} · ${m.name} — ${nf0.format(m.price)} ฿</option>`).join('');\r\n  sel.value = (selected === undefined ? (DEFAULT_MODEL[presetKey] || '') : selected);\r\n}\r\n\r\nfunction applyModel(code) {\r\n  const list = MODELS[state.preset] || [];\r\n  const m = list.find(x => x.code === code);\r\n  if (!m) return;                       // กำหนดเอง → ใช้ราคาตามที่ผู้ใช้แก้\r\n  $('#price').value = m.price;\r\n  if (state.preset === 'laundry' && m.type) {\r\n    const t = LAUNDRY_TYPE[m.type];\r\n    $('#unitPrice').value = t.unitPrice;\r\n    $('#waterL').value = t.waterL;\r\n    $('#elecKW').value = t.elecKW;\r\n    $('#elecHours').value = t.elecHours;\r\n    $('#qty').max = t.qtyMax;\r\n    $('#qty').value = t.baseQty;\r\n    state.scenario = 'base';\r\n    syncScenarioChips();\r\n  }\r\n  render();\r\n}\r\n\r\n/* ---------- render: KPIs ---------- */\r\nfunction setTone(cardId, tone) {\r\n  const el = document.getElementById(cardId);\r\n  if (tone) el.dataset.tone = tone; else el.removeAttribute('data-tone');\r\n}\r\n\r\nfunction renderKPIs(p, r) {\r\n  // ROI\r\n  setKpi('kpiRoi', 'kpiRoiCard', r.roi === Infinity ? '∞' : (!isFinite(r.roi) ? '—' : (r.roi > 5 ? '>500%' : pct(r.roi))));\r\n  setTone('kpiRoiCard', null);\r\n  const roiCard = document.getElementById('kpiRoiCard');\r\n  const ringV = isFinite(r.roi) ? Math.max(0, Math.min(1, r.roi / 0.6)) : 0;\r\n  roiCard.style.setProperty('--v', ringV.toFixed(3));\r\n  $('#kpiRoiSub').textContent = p.mode === 'loan'\r\n    ? `จากเงินดาวน์ ${baht(r.equity)} · กำไร/เดือน ${baht(r.ncf)}`\r\n    : `จากเงินลงทุน ${baht(r.equity)} · กำไร/เดือน ${baht(r.ncf)}`;\r\n\r\n  // Payback\r\n  setKpi('kpiPayback', 'kpiPaybackCard', monthText(r.payback));\r\n  setTone('kpiPaybackCard', r.payback == null ? 'bad' : (r.payback <= 18 ? 'ok' : r.payback <= 30 ? 'warn' : 'bad'));\r\n  $('#kpiPaybackSub').textContent = r.payback == null\r\n    ? 'กระแสเงินสดไม่พอคืนทุน'\r\n    : `นับจากวันติดตั้ง · ภายใน ${p.years} ปี`;\r\n\r\n  // กำไรสุทธิ/เดือน\r\n  setKpi('kpiProfit', 'kpiProfitCard', bahtSigned(r.ncf));\r\n  setTone('kpiProfitCard', r.ncf > 0 ? 'ok' : 'bad');\r\n  $('#kpiProfitSub').textContent = p.mode === 'loan'\r\n    ? `หลังหักค่างวด ${baht(r.pmt)}/เดือน`\r\n    : 'หลังหักต้นทุนดำเนินงาน';\r\n\r\n  // จุดคุ้มทุน\r\n  const be = r.beQty;\r\n  setKpi('kpiBe', 'kpiBeCard', be != null ? nf0.format(Math.ceil(be)) : '—');\r\n  setTone('kpiBeCard', be == null ? 'bad' : (p.qty >= be ? 'ok' : 'warn'));\r\n  $('#kpiBeSub').textContent = be != null\r\n    ? `${PRESETS[state.preset].unit}/วัน (ปัจจุบัน ${nf0.format(p.qty)})`\r\n    : 'กำไรต่อหน่วยติดลบ';\r\n\r\n  $('#topCash').textContent = bahtSigned(r.ncf);\r\n}\r\n\r\n/* ---------- render: verdict ---------- */\r\nfunction renderVerdict(p, r) {\r\n  const cfg = PRESETS[state.preset];\r\n  const ok = r.ncf > 0 && r.payback != null;\r\n  $('#verdictCard').className = 'verdict' + (ok ? '' : ' bad');\r\n\r\n  $('#vInvest').textContent = baht(p.price);\r\n  $('#vProfit').textContent = bahtSigned(r.ncf);\r\n  $('#vPayback').textContent = monthText(r.payback);\r\n\r\n  let txt = `ลงทุนรวม <b>${baht(p.price)}</b>`;\r\n  if (p.mode === 'loan') txt += ` (ดาวน์ ${p.downPct}% = ${baht(r.down)} ผ่อน ${p.term} งวด งวดละ ${baht(r.pmt)})`;\r\n  txt += ` ขายได้ ${nf0.format(p.qty)} ${cfg.unit}/วัน ราคา ${nf2.format(p.unitPrice)} บาท`;\r\n  txt += ` → รายรับ ${baht(r.revenue)}/เดือน`;\r\n  txt += ` หักต้นทุน${p.mode === 'loan' ? 'และค่างวด' : ''} เหลือ <b>${baht(r.ncf)}/เดือน</b>`;\r\n  if (r.payback != null && r.payback > 0) txt += ` คืนทุนภายใน <b>${monthText(r.payback)}</b>`;\r\n  if (isFinite(r.roi) && r.roi > 0) txt += ` (ผลตอบแทน ${r.roi > 5 ? 'มากกว่า 500%' : pct(r.roi, 0)} ต่อปี)`;\r\n  if (!ok) txt = 'ยอดขาย/ราคานี้ยังไม่พอหักต้นทุน — ปรับยอดขายขึ้น หรือลดเงินลงทุน/ค่าเช่าก่อนนำเสนอลูกค้า';\r\n  $('#verdictText').innerHTML = txt;\r\n}\r\n\r\n/* ---------- render: cash vs installment ---------- */\r\nfunction renderCompare(p) {\r\n  const cash = core({ ...p, mode: 'cash' });\r\n  const loan = core({ ...p, mode: 'loan' });\r\n\r\n  const col = (title, tag, r, on) => `\r\n    <div class=\"col ${on ? 'on' : ''}\">\r\n      <h4>${title}${tag ? `<small>${tag}</small>` : ''}</h4>\r\n      <div class=\"row\"><span>เงินที่จ่ายวันแรก</span><b>${baht(r.equity)}</b></div>\r\n      <div class=\"row\"><span>ค่างวด/เดือน</span><b>${r.pmt ? baht(r.pmt) : '—'}</b></div>\r\n      <div class=\"row\"><span>ดอกเบี้ยรวม</span><b>${r.interest ? baht(r.interest) : '—'}</b></div>\r\n      <div class=\"row\"><span>กำไรสุทธิ/เดือน</span><b>${bahtSigned(r.ncf)}</b></div>\r\n      <div class=\"row\"><span>คืนทุน (จากเงินที่จ่ายเอง)</span><b>${monthText(r.payback)}</b></div>\r\n      <div class=\"row\"><span>ผลตอบแทนต่อปี</span><b>${!isFinite(r.roi) ? '—' : (r.roi > 5 ? '>500%' : pct(r.roi, 0))}</b></div>\r\n    </div>`;\r\n\r\n  $('#cmpBox').innerHTML =\r\n    col('💵 ซื้อเงินสด', 'ไม่มีดอกเบี้ย', cash, p.mode === 'cash') +\r\n    col(`🏦 ผ่อน ${p.term} งวด`, 'ใช้เงินเริ่มต้นน้อย', loan, p.mode === 'loan');\r\n\r\n  $('#cmpNote').innerHTML = loan.pmt\r\n    ? `ซื้อเงินสดใช้เงินก้อน ${baht(cash.equity)} แต่ไม่มีภาระรายเดือน · ผ่อนชำระใช้เงินเริ่มต้นเพียง ${baht(loan.equity)} แต่มีค่างวด ${baht(loan.pmt)}/เดือน และดอกเบี้ยรวม ${baht(loan.interest)} ตลอดสัญญา`\r\n    : 'เลือกโหมดผ่อนชำระเพื่อดูตัวเลขฝั่งไฟแนนซ์';\r\n}\r\n\r\n/* ---------- render: advanced metrics ---------- */\r\nfunction renderAdvanced(p, r) {\r\n  $('#advNpv').textContent = bahtSigned(r.npv);\r\n  $('#advIrr').textContent = pctCap(r.irrAnnual);\r\n  $('#advPi').textContent = r.equity > 0 ? ((r.npv + r.equity) / r.equity).toFixed(2) + ' เท่า' : '—';\r\n}\r\n\r\n/* ---------- render: break-even ---------- */\r\nfunction renderBreakEven(p, r) {\r\n  const cfg = PRESETS[state.preset];\r\n  const be = r.beQty;\r\n  $('#beQty').textContent = be != null ? nf0.format(Math.ceil(be)) : '—';\r\n  $('#beQtyUnit').textContent = be != null ? `${cfg.unitShort} (${Math.ceil(be * 30)}/${cfg.unit}/เดือน)` : 'กำไรส่วนเพิ่มติดลบ';\r\n  $('#beRevenue').textContent = r.beRevenue != null ? baht(r.beRevenue) : '—';\r\n  $('#beContrib').textContent = baht(r.contribution);\r\n  $('#beInline').textContent = be != null ? `${nf0.format(Math.ceil(be))} ${cfg.unit}` : '—';\r\n\r\n  const note = $('#beNote');\r\n  if (r.opProfit <= 0) {\r\n    note.className = 'note bad';\r\n    note.innerHTML = `<span>⛔</span><span>ยอดขายปัจจุบัน <b>${nf0.format(p.qty)} ${cfg.unit}/วัน</b> ยังไม่ถึงจุดคุ้มทุน — ต้องขายเพิ่มอีก <b>${be != null ? Math.max(0, Math.ceil(be - p.qty)) : '—'} ${cfg.unit}/วัน</b> หรือปรับราคา/ลดต้นทุนก่อนลงทุน</span>`;\r\n  } else if (be != null && r.beQty > 0) {\r\n    const buffer = (p.qty - be) / p.qty;\r\n    note.className = 'note ok';\r\n    note.innerHTML = `<span>✅</span><span>ยอดขายอยู่เหนือจุดคุ้มทุน <b>${pct(buffer)}</b> — ถ้ายอดขายตกลงเกิน ${pct(buffer)} จะเริ่มขาดทุน (Margin of Safety)</span>`;\r\n  } else {\r\n    note.className = 'note';\r\n    note.innerHTML = '<span>ℹ️</span><span>ไม่มีต้นทุนคงที่/ค่างวด จึงคุ้มทุนทันทีเมื่อขายได้</span>';\r\n  }\r\n}\r\n\r\n/* ---------- render: cost bar ---------- */\r\nfunction renderCostBar(p, r) {\r\n  const items = [\r\n    { label:'ต้นทุนวัตถุดิบ', val:r.raw,   color:'var(--c-raw)' },\r\n    { label:'ค่าธรรมเนียม QR', val:r.qr,  color:'var(--c-qr)' },\r\n    { label:'ค่าไฟฟ้า',       val:r.elec, color:'var(--c-elec)' },\r\n    { label:'ค่าน้ำประปา',     val:r.water, color:'var(--c-water)' },\r\n    { label:'ค่าเช่า + ดูแล',  val:r.fixed, color:'var(--c-fix)' },\r\n    { label:'ค่างวดผ่อน',      val:p.mode === 'loan' ? r.pmt : 0, color:'var(--c-loan)' },\r\n    { label:'กำไร/กระแสเงินสด', val:Math.max(0, r.ncf), color:'var(--c-profit)' }\r\n  ].filter(x => x.val > 0.5);\r\n\r\n  const total = Math.max(r.revenue, items.reduce((s, x) => s + x.val, 0), 1);\r\n  const bar = $('#costBar');\r\n  bar.innerHTML = items.map(x => `<i style=\"width:${(x.val / total * 100).toFixed(2)}%;background:${x.color}\" title=\"${x.label}\"></i>`).join('');\r\n  if (!items.length) bar.innerHTML = '<i style=\"width:100%;background:var(--surface-3)\"></i>';\r\n\r\n  $('#costLegend').innerHTML = items.map(x => `\r\n    <div><i style=\"background:${x.color}\"></i>${x.label}<b>${baht(x.val)}</b></div>\r\n  `).join('') + `<div><i style=\"background:var(--line)\"></i>รายรับรวม<b>${baht(r.revenue)}</b></div>`;\r\n\r\n  $('#revHint').textContent = `รายรับ ${baht(r.revenue)}/เดือน · กำไรดำเนินงาน ${baht(r.opProfit)} (${pct(r.margin)} ของรายรับ)`;\r\n}\r\n\r\n/* ---------- render: sensitivity ---------- */\r\nfunction renderSensitivity(p) {\r\n  const scales = [\r\n    { s:0.7,  label:'−30%' },\r\n    { s:0.85, label:'−15%' },\r\n    { s:1.0,  label:'ตามเป้า' },\r\n    { s:1.15, label:'+15%' },\r\n    { s:1.3,  label:'+30%' }\r\n  ];\r\n  const grid = $('#sensGrid');\r\n  grid.innerHTML = scales.map(sc => {\r\n    const q = Math.max(0, p.qty * sc.s);\r\n    const r = core({ ...p, qty:q });\r\n    const tone = r.payback == null ? 'var(--bad)' : (r.payback <= 18 ? 'var(--ok)' : 'var(--warn)');\r\n    return `<div class=\"cell ${sc.s === 1 ? 'on' : ''}\">\r\n      <em>${sc.label}</em>\r\n      <b style=\"color:${tone}\">${r.payback == null ? 'ไม่คืนทุน' : Math.ceil(r.payback) + ' เดือน'}</b>\r\n      <small>${nf0.format(q)} /วัน · ROI ${isFinite(r.roi) ? pct(r.roi, 0) : '∞'}</small>\r\n    </div>`;\r\n  }).join('');\r\n}\r\n\r\n/* ---------- render: chart ---------- */\r\nfunction drawChart(p, r) {\r\n  const cv = $('#cashChart');\r\n  if (!cv || cv.offsetParent === null) return;\r\n  const dpr = window.devicePixelRatio || 1;\r\n  const W = cv.clientWidth || 600, H = cv.clientHeight || 260;\r\n  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);\r\n  const ctx = cv.getContext('2d');\r\n  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\r\n  ctx.clearRect(0, 0, W, H);\r\n\r\n  const cs = getComputedStyle(document.documentElement);\r\n  const cLine = cs.getPropertyValue('--line').trim() || '#e3e9f3';\r\n  const cInk3 = cs.getPropertyValue('--ink-3').trim() || '#8b98ac';\r\n  const cGrid = cs.getPropertyValue('--grid').trim() || '#e7edf7';\r\n  const cBrand = cs.getPropertyValue('--brand').trim() || '#3b5bfd';\r\n  const cOk = cs.getPropertyValue('--ok').trim() || '#0e9f6e';\r\n  const cBad = cs.getPropertyValue('--bad').trim() || '#d63d3d';\r\n\r\n  const series = r.cumSeries;\r\n  const padL = 54, padR = 14, padT = 16, padB = 26;\r\n  const plotW = Math.max(10, W - padL - padR), plotH = Math.max(10, H - padT - padB);\r\n\r\n  const vals = series.map(d => d.cum);\r\n  let mn = Math.min(0, ...vals), mx = Math.max(0, ...vals);\r\n  if (mn === mx) { mx = 1; mn = -1; }\r\n  const span = mx - mn;\r\n  mn -= span * 0.12; mx += span * 0.12;\r\n\r\n  const X = m => padL + (m / series[series.length - 1].m) * plotW;\r\n  const Y = v => padT + (1 - (v - mn) / (mx - mn)) * plotH;\r\n\r\n  // grid\r\n  ctx.strokeStyle = cGrid; ctx.lineWidth = 1;\r\n  ctx.font = '10px Prompt, sans-serif'; ctx.fillStyle = cInk3; ctx.textAlign = 'right'; ctx.textBaseline = 'middle';\r\n  for (let i = 0; i <= 4; i++) {\r\n    const v = mn + (mx - mn) * i / 4;\r\n    const y = Y(v);\r\n    ctx.beginPath(); ctx.moveTo(padL, y); ctx.lineTo(W - padR, y); ctx.stroke();\r\n    ctx.fillText(compact(v), padL - 8, y);\r\n  }\r\n\r\n  // zero line\r\n  const y0 = Y(0);\r\n  ctx.strokeStyle = cInk3; ctx.setLineDash([4, 4]); ctx.globalAlpha = .55;\r\n  ctx.beginPath(); ctx.moveTo(padL, y0); ctx.lineTo(W - padR, y0); ctx.stroke();\r\n  ctx.setLineDash([]); ctx.globalAlpha = 1;\r\n\r\n  // area\r\n  const last = series[series.length - 1];\r\n  const endColor = last.cum >= 0 ? cOk : cBad;\r\n  const grad = ctx.createLinearGradient(0, padT, 0, padT + plotH);\r\n  const endRGB = last.cum >= 0 ? '14,159,110' : '214,61,61';\r\n  grad.addColorStop(0, `rgba(${endRGB},.26)`);\r\n  grad.addColorStop(1, `rgba(${endRGB},0)`);\r\n  ctx.beginPath();\r\n  ctx.moveTo(X(0), y0);\r\n  series.forEach(d => ctx.lineTo(X(d.m), Y(d.cum)));\r\n  ctx.lineTo(X(last.m), y0);\r\n  ctx.closePath();\r\n  ctx.fillStyle = grad; ctx.fill();\r\n\r\n  // line\r\n  ctx.beginPath();\r\n  series.forEach((d, i) => i ? ctx.lineTo(X(d.m), Y(d.cum)) : ctx.moveTo(X(d.m), Y(d.cum)));\r\n  ctx.strokeStyle = cBrand; ctx.lineWidth = 2.2; ctx.lineJoin = 'round'; ctx.stroke();\r\n\r\n  // payback marker\r\n  if (r.payback != null && r.payback > 0 && r.payback <= last.m) {\r\n    const px = X(r.payback);\r\n    ctx.strokeStyle = cOk; ctx.setLineDash([5, 4]); ctx.lineWidth = 1.4;\r\n    ctx.beginPath(); ctx.moveTo(px, padT); ctx.lineTo(px, padT + plotH); ctx.stroke();\r\n    ctx.setLineDash([]);\r\n    ctx.fillStyle = cOk; ctx.beginPath(); ctx.arc(px, Y(0), 4, 0, Math.PI * 2); ctx.fill();\r\n\r\n    ctx.fillStyle = cOk; ctx.font = '600 10px Prompt, sans-serif'; ctx.textAlign = 'left'; ctx.textBaseline = 'top';\r\n    const txt = 'คืนทุน ' + Math.ceil(r.payback) + ' เดือน';\r\n    const tx = Math.min(px + 7, W - padR - ctx.measureText(txt).width);\r\n    ctx.fillText(txt, tx, padT + 2);\r\n  }\r\n\r\n  // x labels\r\n  ctx.fillStyle = cInk3; ctx.font = '10px Prompt, sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'top';\r\n  const yearsCount = Math.round(last.m / 12);\r\n  for (let y = 0; y <= yearsCount; y++) {\r\n    const m = Math.min(y * 12, last.m);\r\n    ctx.fillText(y === 0 ? 'เริ่ม' : 'ปี ' + y, X(m), padT + plotH + 7);\r\n  }\r\n\r\n  chartGeom = { padL, padR, padT, plotH, W, H, series, X, Y, lastM: last.m };\r\n}\r\n\r\nfunction handleChartMove(e) {\r\n  const tip = document.getElementById('chartTip');\r\n  if (!chartGeom || state.view !== 'cashflow') { tip.classList.remove('on'); return; }\r\n  const cv = document.getElementById('cashChart');\r\n  const rect = cv.getBoundingClientRect();\r\n  const x = e.clientX - rect.left;\r\n  const g = chartGeom;\r\n  const plotW = g.W - g.padL - g.padR;\r\n  if (x < g.padL - 8 || x > g.W - g.padR + 8) { tip.classList.remove('on'); return; }\r\n  const t = Math.max(0, Math.min(1, (x - g.padL) / plotW));\r\n  const m = Math.round(t * g.lastM);\r\n  const pt = g.series[m];\r\n  if (!pt) return;\r\n  tip.innerHTML = `เดือนที่ <b>${m}</b> · สะสม <b>${bahtSigned(pt.cum)}</b>`;\r\n  tip.style.left = g.X(m) + 'px';\r\n  tip.style.top = g.Y(pt.cum) + 'px';\r\n  tip.classList.add('on');\r\n}\r\n\r\n/* ---------- render: yearly table ---------- */\r\nfunction renderYearTable(p, r) {\r\n  const rows = [];\r\n  let cum = -r.equity;\r\n  let pv = -r.equity;\r\n  const rDisc = p.discount / 100;\r\n  for (let y = 1; y <= p.years; y++) {\r\n    let rev = 0, opx = 0, pay = 0, cf = 0, pvY = 0;\r\n    for (let m = (y - 1) * 12 + 1; m <= y * 12; m++) {\r\n      const row = r.monthly[m - 1];\r\n      if (!row) continue;\r\n      rev += row.rev; opx += row.opex; pay += row.pay; cf += row.cf;\r\n      pvY += row.cf / Math.pow(1 + rDisc, row.m / 12);\r\n    }\r\n    cum += cf; pv += pvY;\r\n    rows.push({ y, rev, opx, pay, cf, cum, pv });\r\n  }\r\n  $('#yearBody').innerHTML = rows.map(x => `\r\n    <tr>\r\n      <td class=\"em\">ปี ${x.y}</td>\r\n      <td>${baht(x.rev)}</td>\r\n      <td>${baht(-x.opx)}</td>\r\n      <td>${x.pay ? baht(-x.pay) : '—'}</td>\r\n      <td class=\"${x.cf >= 0 ? 'pos' : 'neg'}\">${bahtSigned(x.cf)}</td>\r\n      <td class=\"${x.cum >= 0 ? 'pos' : 'neg'}\">${bahtSigned(x.cum)}</td>\r\n      <td>${bahtSigned(x.pv)}</td>\r\n    </tr>`).join('');\r\n\r\n  $('#chartHint').textContent = `เงินลงทุนตั้งต้น ${baht(r.equity)} · สิ้นปีที่ ${p.years} กระแสเงินสดสะสม ${bahtSigned(rows[rows.length - 1].cum)}`;\r\n}\r\n\r\n/* ---------- render: loan ---------- */\r\nfunction renderLoan(p, r) {\r\n  const box = $('#loanSummary');\r\n  const tbody = $('#amortBody');\r\n\r\n  if (p.mode !== 'loan') {\r\n    $('#loanHint').textContent = 'โหมดซื้อเงินสด';\r\n    tbody.innerHTML = `<tr><td colspan=\"5\" class=\"empty\">โหมดซื้อเงินสด — ไม่มีตารางผ่อนชำระ</td></tr>`;\r\n    $('#amortHint').textContent = '—';\r\n    box.innerHTML = `\r\n      <div class=\"empty\">\r\n        <p style=\"margin-bottom:10px\">ตอนนี้ใช้โหมดซื้อเงินสด — เปรียบเทียบได้ว่าถ้าเลือกผ่อน sẽกระทบกระแสเงินสดอย่างไร</p>\r\n        <button class=\"btn solid\" id=\"btnSwitchLoan\" type=\"button\">เปรียบเทียบแบบผ่อนชำระ</button>\r\n      </div>`;\r\n    const b = $('#btnSwitchLoan');\r\n    if (b) b.onclick = () => setMode('loan');\r\n    return;\r\n  }\r\n\r\n  const n = Math.max(1, p.term);\r\n  const iM = r.principal > 0 ? irr([-r.principal, ...Array(n).fill(r.pmt)]) : 0;\r\n  const aprNominal = isFinite(iM) ? iM * 12 : NaN;\r\n  const aprEffective = isFinite(iM) ? Math.pow(1 + iM, 12) - 1 : NaN;\r\n\r\n  const totalPay = r.pmt * n;\r\n  const interestPct = r.principal > 0 ? r.interest / r.principal : 0;\r\n\r\n  // benchmark: same principal, reducing-balance (annuity) at the discount rate\r\n  const iBench = p.discount / 100 / 12;\r\n  const pmtBench = iBench > 0 ? r.principal * iBench / (1 - Math.pow(1 + iBench, -n)) : r.principal / n;\r\n  const benchInterest = pmtBench * n - r.principal;\r\n  const benchDiff = r.pmt - pmtBench;\r\n\r\n  $('#loanHint').textContent = `${p.downPct}% ดาวน์ · ${n} งวด · ดอกเบี้ยคงที่ ${nf2.format(p.flatRate)}%/เดือน`;\r\n  $('#amortHint').textContent = `รวม ${n} งวด · ดอกเบี้ยรวม ${baht(r.interest)}`;\r\n\r\n  box.innerHTML = `\r\n    <div class=\"loan-cards\">\r\n      <div class=\"lc\"><span>ราคาสุทธิ</span><b>${baht(p.price)}</b></div>\r\n      <div class=\"lc\"><span>เงินดาวน์ (${p.downPct}%)</span><b>${baht(r.down)}</b></div>\r\n      <div class=\"lc\"><span>ยอดจัดไฟแนนซ์</span><b>${baht(r.principal)}</b></div>\r\n      <div class=\"lc hl\"><span>ค่างวด / เดือน</span><b>${baht(r.pmt)}</b></div>\r\n      <div class=\"lc\"><span>ดอกเบี้ยรวม</span><b>${baht(r.interest)}</b></div>\r\n      <div class=\"lc\"><span>ยอดชำระรวม</span><b>${baht(totalPay)}</b></div>\r\n      <div class=\"lc\"><span>APR แท้จริง / ปี</span><b>${isFinite(aprNominal) ? pct(aprNominal) : '—'}</b></div>\r\n      <div class=\"lc\"><span>ถ้าลดต้นลดดอก ${nf1.format(p.discount)}%/ปี</span><b>${baht(pmtBench)}</b></div>\r\n    </div>\r\n    <div class=\"note ${benchDiff > 0 ? '' : 'ok'}\" style=\"margin-top:12px\">\r\n      <span>🧮</span>\r\n      <span>ดอกเบี้ยคงที่ ${nf2.format(p.flatRate)}%/เดือน = <b>${pct(interestPct)}</b> ของยอดจัดตลอดสัญญา\r\n      คิดเป็นดอกเบี้ยแท้จริง (APR) ประมาณ <b>${isFinite(aprNominal) ? pct(aprNominal) : '—'}</b> ต่อปี\r\n      — ถ้ากู้แบบลดต้นลดดอกที่ ${nf1.format(p.discount)}%/ปี ค่างวดจะอยู่ที่ <b>${baht(pmtBench)}</b>\r\n      (${benchDiff >= 0 ? 'ถูกกว่า' : 'แพงกว่า'} ${baht(Math.abs(benchDiff))}/เดือน, ดอกเบี้ยต่างกัน ${baht(Math.abs(r.interest - benchInterest))} ตลอดสัญญา)\r\n      ${p.downPct >= 50 ? ' · เงินดาวน์ 50% ขึ้นไป: ยกเว้นผู้ค้ำประกันได้' : ''}</span>\r\n    </div>`;\r\n\r\n  // amortization (flat rate → interest constant)\r\n  const intPerMonth = r.interest / n;\r\n  const prinPerMonth = r.principal / n;\r\n  let bal = r.principal;\r\n  let html = '';\r\n  for (let m = 1; m <= n; m++) {\r\n    const isLast = m === n;\r\n    const intr = isLast ? r.pmt - bal : intPerMonth;\r\n    const prin = isLast ? bal : prinPerMonth;\r\n    bal = Math.max(0, bal - prin);\r\n    html += `<tr>\r\n      <td class=\"em\">${m}</td>\r\n      <td>${baht(r.pmt)}</td>\r\n      <td>${baht(prin)}</td>\r\n      <td>${baht(intr)}</td>\r\n      <td>${baht(bal)}</td>\r\n    </tr>`;\r\n  }\r\n  tbody.innerHTML = html;\r\n}\r\n\r\n/* ---------- rate matrix ---------- */\r\nfunction renderMatrix() {\r\n  const host = $('#rateMatrix');\r\n  const down = num('downPct'), term = num('term');\r\n  const head = `<tr><th class=\"corner\">ดาวน์ \\\\ งวด</th>${RATE.terms.map(t => `<th>${t}</th>`).join('')}</tr>`;\r\n  const body = RATE.downs.map((d, i) => {\r\n    const cells = RATE.terms.map((t, j) => {\r\n      const active = d === down && t === term;\r\n      return `<td><button type=\"button\" class=\"${active ? 'on' : ''}\" data-down=\"${d}\" data-term=\"${t}\">${RATE.rows[i][j].toFixed(2)}%</button></td>`;\r\n    }).join('');\r\n    return `<tr><th>${d}%</th>${cells}</tr>`;\r\n  }).join('');\r\n  host.innerHTML = `<table><thead>${head}</thead><tbody>${body}</tbody></table>`;\r\n  $$('#rateMatrix button').forEach(b => {\r\n    b.addEventListener('click', () => {\r\n      $('#downPct').value = b.dataset.down;\r\n      $('#term').value = b.dataset.term;\r\n      $('#flatRate').value = lookupRate(Number(b.dataset.down), Number(b.dataset.term)).toFixed(2);\r\n      render();\r\n    });\r\n  });\r\n}\r\n\r\n/* ---------- master render ---------- */\r\nfunction render() {\r\n  const p = readInputs();\r\n\r\n  // panel visibility\r\n  const isLoan = p.mode === 'loan';\r\n  $('#loanInputs').style.display = isLoan ? '' : 'none';\r\n  $('#cashHint').hidden = isLoan;\r\n\r\n  renderLabels(p);\r\n  const r = core(p);\r\n  renderKPIs(p, r);\r\n  renderVerdict(p, r);\r\n  renderBreakEven(p, r);\r\n  renderCostBar(p, r);\r\n  renderCompare(p);\r\n  renderSensitivity(p);\r\n  renderAdvanced(p, r);\r\n  renderYearTable(p, r);\r\n  renderLoan(p, r);\r\n  renderMatrix();\r\n  if (state.view === 'cashflow') drawChart(p, r);\r\n}\r\n\r\n/* ---------- presets / scenario ---------- */\r\nfunction applyPreset(key) {\r\n  state.preset = key;\r\n  const c = PRESETS[key];\r\n  $('#price').value = c.price;\r\n  $('#unitPrice').min = c.unitMin;\r\n  $('#unitPrice').max = c.unitMax;\r\n  $('#unitPrice').value = c.unitPrice;\r\n  $('#qty').max = c.qtyMax;\r\n  $('#qty').value = c.baseQty;\r\n  $('#rawCost').value = c.rawCost;\r\n  $('#qrShare').value = c.qrShare;\r\n  $('#qrFee').value = c.qrFee;\r\n  $('#elecKW').value = c.elecKW;\r\n  $('#elecHours').value = c.elecHours;\r\n  $('#elecRate').value = c.elecRate;\r\n  $('#waterL').value = c.waterL;\r\n  $('#waterRate').value = c.waterRate;\r\n  $('#rent').value = c.rent;\r\n  $('#maint').value = c.maint;\r\n  $('#modelBlock').hidden = !(MODELS[key] && MODELS[key].length);\r\n  $('#modelLabel').textContent = MODEL_LABEL[key] || 'รุ่นสินค้าอ้างอิง';\r\n  $('#installBlock').hidden = key !== 'laundry';\r\n  $('#investHint').hidden = key !== 'laundry';\r\n  $('#install').value = key === 'laundry' ? 6010 : 0;\r\n  populateModels(key);\r\n  if (key === 'laundry') {\r\n    const t = LAUNDRY_TYPE.top;\r\n    $('#unitPrice').min = 10; $('#unitPrice').max = 100;\r\n    $('#elecKW').value = t.elecKW; $('#elecHours').value = t.elecHours;\r\n    $('#waterL').value = t.waterL; $('#qty').max = t.qtyMax; $('#qty').value = t.baseQty;\r\n  }\r\n  state.scenario = 'base';\r\n  syncScenarioChips();\r\n  applyRateFromTable();\r\n  render();\r\n}\r\n\r\nfunction syncScenarioChips() {\r\n  $$('#scenarioSeg button').forEach(b => b.classList.toggle('on', b.dataset.scen === state.scenario));\r\n  const map = { low:'ต่ำกว่าเป้า 30%', base:'ตามเป้า', high:'สูงกว่าเป้า 30%' };\r\n  $('#scenOut').textContent = map[state.scenario] || 'กำหนดเอง';\r\n}\r\n\r\nfunction applyScenario(scen) {\r\n  const c = PRESETS[state.preset];\r\n  const f = { low:0.7, base:1, high:1.3 }[scen];\r\n  state.scenario = scen;\r\n  $('#qty').value = Math.round(c.baseQty * f);\r\n  syncScenarioChips();\r\n  render();\r\n}\r\n\r\nfunction applyRateFromTable() {\r\n  const rate = lookupRate(num('downPct'), num('term'));\r\n  $('#flatRate').value = rate.toFixed(2);\r\n}\r\n\r\n/* ---------- mode ---------- */\r\nfunction setMode(mode) {\r\n  state.mode = mode;\r\n  $$('#modeSeg button').forEach(b => b.classList.toggle('on', b.dataset.mode === mode));\r\n  render();\r\n}\r\n\r\n/* ---------- theme ---------- */\r\nfunction setTheme(t) {\r\n  document.documentElement.dataset.theme = t;\r\n  localStorage.setItem('roiStudioTheme', t);\r\n  $('#btnTheme').textContent = t === 'dark' ? '☀' : '◐';\r\n  render();\r\n}\r\n\r\n/* ---------- toast ---------- */\r\nlet toastTimer;\r\nfunction toast(msg) {\r\n  const el = $('#toast');\r\n  el.textContent = msg;\r\n  el.classList.add('on');\r\n  clearTimeout(toastTimer);\r\n  toastTimer = setTimeout(() => el.classList.remove('on'), 2000);\r\n}\r\n\r\n/* ---------- summary (customer facing) ---------- */\r\nfunction summaryText() {\r\n  const p = readInputs(), r = core(p), c = PRESETS[state.preset];\r\n  const lines = [];\r\n  lines.push(`ข้อเสนอการลงทุน — ${c.label}`);\r\n  lines.push(`• เงินลงทุนรวม ${baht(p.price)}` + (p.mode === 'loan'\r\n    ? ` (ดาวน์ ${p.downPct}% = ${baht(r.down)} · ผ่อน ${p.term} งวด งวดละ ${baht(r.pmt)})`\r\n    : ' (ซื้อเงินสด)'));\r\n  lines.push(`• ยอดขาย ${nf0.format(p.qty)} ${c.unit}/วัน × ${nf2.format(p.unitPrice)} บาท = รายรับ ${baht(r.revenue)}/เดือน`);\r\n  lines.push(`• ต้นทุนดำเนินงาน ${baht(r.opex)}/เดือน` + (r.pmt ? ` + ค่างวด ${baht(r.pmt)}` : ''));\r\n  lines.push(`• กำไรสุทธิ ${baht(r.ncf)}/เดือน`);\r\n  if (r.payback != null) lines.push(`• คืนทุนประมาณ ${monthText(r.payback)}`);\r\n  if (isFinite(r.roi)) lines.push(`• ผลตอบแทนต่อปี ${pct(r.roi, 0)}`);\r\n  if (r.beQty != null) lines.push(`• จุดคุ้มทุน ${nf0.format(Math.ceil(r.beQty))} ${c.unit}/วัน`);\r\n  lines.push('');\r\n  lines.push('(ตัวเลขเป็นการประมาณการจากแบบจำลอง ไม่ใช่การรับประกันผลตอบแทน)');\r\n  return lines.join('\\n');\r\n}\r\n\r\n/* ---------- bind ---------- */\r\nfunction bind() {\r\n  // preset chips\r\n  $$('#presetChips .chip').forEach(b => b.addEventListener('click', () => {\r\n    $$('#presetChips .chip').forEach(x => x.classList.remove('on'));\r\n    b.classList.add('on');\r\n    applyPreset(b.dataset.preset);\r\n  }));\r\n\r\n  // scenario\r\n  $$('#scenarioSeg button').forEach(b => b.addEventListener('click', () => applyScenario(b.dataset.scen)));\r\n\r\n  // mode\r\n  $$('#modeSeg button').forEach(b => b.addEventListener('click', () => setMode(b.dataset.mode)));\r\n\r\n  // views\r\n  $$('#viewSeg button').forEach(b => b.addEventListener('click', () => {\r\n    state.view = b.dataset.view;\r\n    $$('#viewSeg button').forEach(x => x.classList.toggle('on', x === b));\r\n    $$('.view').forEach(v => { v.hidden = v.id !== 'view-' + state.view; });\r\n    $('#chartTip').classList.remove('on');\r\n    if (state.view === 'cashflow') requestAnimationFrame(() => drawChart(readInputs(), core(readInputs())));\r\n  }));\r\n\r\n  // all inputs → render\r\n  const ids = ['price','years','discount','salvage','qty','unitPrice','rawCost','qrShare','qrFee',\r\n    'elecKW','elecHours','elecRate','waterL','waterRate','rent','maint','downPct','term','flatRate','install'];\r\n  ids.forEach(id => {\r\n    const el = document.getElementById(id);\r\n    if (!el) return;\r\n    const evt = (el.tagName === 'SELECT' || el.type === 'number') ? 'input' : 'input';\r\n    el.addEventListener(evt, () => {\r\n      if (id === 'qty') { state.scenario = 'custom'; syncScenarioChips(); }\r\n      if (id === 'downPct' || id === 'term') applyRateFromTable();\r\n      if (id === 'price') { const s = $('#modelSel'); if (s && s.value) s.value = ''; }\r\n      render();\r\n    });\r\n  });\r\n\r\n  // actions\r\n  $('#modelSel').addEventListener('change', e => applyModel(e.target.value));\r\n  $$('#boqChips .chip').forEach(b => b.addEventListener('click', () => {\r\n    $$('#boqChips .chip').forEach(x => x.classList.remove('on'));\r\n    b.classList.add('on');\r\n    $('#install').value = BOQ_INSTALL[b.dataset.n];\r\n    render();\r\n  }));\r\n\r\n  $('#btnPrint').addEventListener('click', () => window.print());\r\n  $('#btnReset').addEventListener('click', () => {\r\n    $('#years').value = 5; $('#discount').value = 8; $('#salvage').value = 0;\r\n    $('#downPct').value = 20; $('#term').value = 24; $('#modeSeg [data-mode=\"cash\"]').click();\r\n    applyPreset(state.preset);\r\n    toast('รีเซ็ตค่าตั้งต้นแล้ว');\r\n  });\r\n  $('#btnCopy').addEventListener('click', async () => {\r\n    const txt = summaryText();\r\n    try { await navigator.clipboard.writeText(txt); toast('คัดลอกข้อความนำเสนอแล้ว'); }\r\n    catch { toast('คัดลอกไม่สำเร็จ — เลือกข้อความเอง'); }\r\n  });\r\n  $('#btnTheme').addEventListener('click', () => {\r\n    setTheme(document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark');\r\n  });\r\n\r\n  // resize → redraw chart\r\n  let rt;\r\n  window.addEventListener('resize', () => {\r\n    clearTimeout(rt);\r\n    rt = setTimeout(() => {\r\n      if (state.view === 'cashflow') { const p = readInputs(); drawChart(p, core(p)); }\r\n    }, 120);\r\n  });\r\n\r\n  // chart hover tooltip\r\n  const chartEl = $('#cashChart');\r\n  chartEl.addEventListener('mousemove', handleChartMove);\r\n  chartEl.addEventListener('mouseleave', () => $('#chartTip').classList.remove('on'));\r\n\r\n  // hero spotlight\r\n  const hero = document.getElementById('kpiRoiCard');\r\n  hero.addEventListener('mousemove', e => {\r\n    const rect = hero.getBoundingClientRect();\r\n    hero.style.setProperty('--mx', ((e.clientX - rect.left) / rect.width * 100).toFixed(1) + '%');\r\n    hero.style.setProperty('--my', ((e.clientY - rect.top) / rect.height * 100).toFixed(1) + '%');\r\n  });\r\n}\r\n\r\n/* ---------- boot ---------- */\r\ndocument.addEventListener('DOMContentLoaded', () => {\r\n  const saved = localStorage.getItem('roiStudioTheme');\r\n  if (saved) { document.documentElement.dataset.theme = saved; $('#btnTheme').textContent = saved === 'dark' ? '☀' : '◐'; }\r\n  bind();\r\n  applyPreset('alkaline');\r\n});\r\n<\/script>\r\n</body>\r\n</html>\r\n";
